import type { RawQ } from "../types";
// Tafsīr of selected passages and surahs 18–114 (al-Kahf to al-Nās) by verse key, after the classical tafāsīr. Draft content, needs scholarly review.
export const QS: RawQ[] = [
  // ---------- stage 1 ----------
  { id: "tfs-001", s: "tafsir", g: 1, d: 1, t: ["al-kahf", "people-of-the-cave"], src: "Ibn Kathīr, Tafsīr, on 18:9–10", v: "18:10",
    en: ["Who are the people described in the verse shown?", ["Young believers who took refuge in a cave", "Disciples of ʿĪsā hiding in a ship", "Soldiers of Firʿawn fleeing the sea", "Merchants of Quraysh lost in the desert"], "The verse shows the youths of the cave (aṣḥāb al-kahf), who fled with their faith from a disbelieving people and asked their Lord for mercy and right guidance."],
    de: ["Wer wird in der angezeigten Āya beschrieben?", ["Junge Gläubige, die in einer Höhle Zuflucht suchten", "Jünger ʿĪsās, die sich in einem Schiff versteckten", "Soldaten Firʿawns auf der Flucht vor dem Meer", "Händler der Quraisch, die sich in der Wüste verirrten"], "Die Āya zeigt die Jünglinge der Höhle (aṣḥāb al-kahf), die mit ihrem Glauben vor einem ungläubigen Volk flohen und ihren Herrn um Barmherzigkeit und Rechtleitung baten."],
    ar: ["مَن الذين تصفهم الآية المعروضة؟", ["فتية مؤمنون لجؤوا إلى كهف", "حواريو عيسى اختبؤوا في سفينة", "جنود فرعون فرّوا من البحر", "تجار من قريش ضلّوا في الصحراء"], "الآية في أصحاب الكهف، فتية فرّوا بدينهم من قوم كافرين وسألوا ربهم الرحمة والرشد."] },

  { id: "tfs-002", s: "tafsir", g: 1, d: 1, t: ["al-kahf", "surah-themes"], src: "Ibn Kathīr, Tafsīr, introduction to Sūrat al-Kahf", v: "18:83",
    en: ["The verse shown opens one of the four great stories of Sūrat al-Kahf. Which story belongs to this surah?", ["Dhū al-Qarnayn and the barrier", "Yūsuf and his brothers", "The she-camel of Ṣāliḥ", "The People of the Elephant"], "The four stories of al-Kahf are the youths of the cave, the owner of the two gardens, Mūsā and al-Khiḍr, and Dhū al-Qarnayn. Yūsuf's story is in Sūrat Yūsuf, Ṣāliḥ's she-camel in several Meccan surahs, and the Elephant in Sūrat al-Fīl."],
    de: ["Die angezeigte Āya eröffnet eine der vier großen Geschichten der Sūrat al-Kahf. Welche Geschichte gehört zu dieser Sure?", ["Ḏū al-Qarnain und der Damm", "Yūsuf und seine Brüder", "Die Kamelstute Ṣāliḥs", "Die Leute des Elefanten"], "Die vier Geschichten von al-Kahf sind die Jünglinge der Höhle, der Besitzer der zwei Gärten, Mūsā und al-Ḫiḍr sowie Ḏū al-Qarnain. Yūsuf steht in Sūrat Yūsuf, die Kamelstute in mehreren mekkanischen Suren, der Elefant in Sūrat al-Fīl."],
    ar: ["الآية المعروضة تفتتح إحدى القصص الأربع الكبرى في سورة الكهف. أيّ هذه القصص من هذه السورة؟", ["ذو القرنين والسدّ", "يوسف وإخوته", "ناقة صالح", "أصحاب الفيل"], "قصص الكهف الأربع: أصحاب الكهف، وصاحب الجنتين، وموسى والخضر، وذو القرنين. أما قصة يوسف ففي سورته، والناقة في سور مكية عدة، والفيل في سورة الفيل."] },

  { id: "tfs-003", s: "tafsir", g: 1, d: 1, t: ["maryam", "surah-names"], src: "al-Suyūṭī, al-Itqān fī ʿUlūm al-Qurʾān, ch. on the names of the surahs", v: "19:16",
    en: ["Sūra 19, whose verse is shown, is named after whom?", ["Maryam, the mother of ʿĪsā", "Āsiya, the wife of Firʿawn", "Ḥawwāʾ, the wife of Ādam", "Hājar, the mother of Ismāʿīl"], "Sūra 19 is named Maryam; the verse shown begins her story, when she withdrew from her family to a place in the east. She is the only woman mentioned by name in the Quran."],
    de: ["Nach wem ist Sure 19, deren Āya angezeigt wird, benannt?", ["Maryam, der Mutter ʿĪsās", "Āsiya, der Frau Firʿawns", "Ḥawwāʾ, der Frau Ādams", "Hāǧar, der Mutter Ismāʿīls"], "Sure 19 heißt Maryam; die angezeigte Āya beginnt ihre Geschichte, als sie sich von ihrer Familie an einen östlichen Ort zurückzog. Sie ist die einzige Frau, die im Koran namentlich genannt wird."],
    ar: ["باسم مَن سُمّيت السورة التاسعة عشرة التي تُعرض آيتها؟", ["مريم أم عيسى", "آسية امرأة فرعون", "حواء زوج آدم", "هاجر أم إسماعيل"], "السورة التاسعة عشرة سورة مريم، والآية المعروضة تبدأ قصتها حين اعتزلت أهلها إلى مكان في جهة الشرق، وهي المرأة الوحيدة المذكورة باسمها في القرآن."] },

  { id: "tfs-004", s: "tafsir", g: 1, d: 2, t: ["ta-ha", "musa"], src: "Ibn Kathīr, Tafsīr, on 20:9–12", v: "20:12",
    en: ["When Mūsā came to the fire, what was he commanded in the verse shown?", ["To take off his sandals in the sacred valley", "To throw his staff into the river", "To return at once to Firʿawn's palace", "To fast for forty days on the mountain"], "In the valley of Ṭuwā Mūsā was called and told to remove his sandals, for he was in the sacred valley; the commission to go to Firʿawn comes later in the passage."],
    de: ["Was wurde Mūsā in der angezeigten Āya befohlen, als er zum Feuer kam?", ["Seine Sandalen im heiligen Tal auszuziehen", "Seinen Stab in den Fluss zu werfen", "Sofort zum Palast Firʿawns zurückzukehren", "Vierzig Tage auf dem Berg zu fasten"], "Im Tal Ṭuwā wurde Mūsā gerufen und aufgefordert, seine Sandalen auszuziehen, denn er befand sich im heiligen Tal; der Auftrag, zu Firʿawn zu gehen, folgt erst später im Abschnitt."],
    ar: ["بماذا أُمر موسى في الآية المعروضة حين أتى النار؟", ["أن يخلع نعليه في الوادي المقدس", "أن يلقي عصاه في النهر", "أن يعود فورًا إلى قصر فرعون", "أن يصوم أربعين يومًا على الجبل"], "نودي موسى في وادي طوى وأُمر بخلع نعليه لأنه في الوادي المقدس، وأما الأمر بالذهاب إلى فرعون فيأتي بعد ذلك في السياق."] },

  { id: "tfs-005", s: "tafsir", g: 1, d: 1, t: ["luqman", "tawhid"], src: "Ibn Kathīr, Tafsīr, on 31:13", v: "31:13",
    en: ["What is the first piece of advice Luqmān gives his son in the verse shown?", ["Not to associate partners with Allah", "To honour his guests generously", "To speak little and listen much", "To seek knowledge in distant lands"], "Luqmān begins with tawḥīd: he forbids his son shirk and calls it a tremendous wrong (ẓulm ʿaẓīm), since it gives worship to one who has no right to it."],
    de: ["Welchen ersten Rat gibt Luqmān seinem Sohn in der angezeigten Āya?", ["Allah keine Teilhaber beizugesellen", "Seine Gäste großzügig zu ehren", "Wenig zu reden und viel zuzuhören", "Wissen in fernen Ländern zu suchen"], "Luqmān beginnt mit dem Tauḥīd: Er verbietet seinem Sohn den Schirk und nennt ihn ein gewaltiges Unrecht (ẓulm ʿaẓīm), weil er Anbetung jemandem gibt, dem sie nicht zusteht."],
    ar: ["ما أول وصية أوصى بها لقمان ابنه في الآية المعروضة؟", ["ألّا يشرك بالله", "أن يكرم ضيفه", "أن يقلّ الكلام ويكثر الاستماع", "أن يطلب العلم في البلاد البعيدة"], "بدأ لقمان بالتوحيد فنهى ابنه عن الشرك ووصفه بأنه ظلم عظيم، لأنه صرف للعبادة إلى من لا يستحقها."] },

  { id: "tfs-006", s: "tafsir", g: 1, d: 1, t: ["ya-sin", "surah-names"], src: "al-Suyūṭī, al-Itqān fī ʿUlūm al-Qurʾān, ch. on the names of the surahs", v: "36:1",
    en: ["Where does the name of Sūrat Yā Sīn come from?", ["From the two separate letters that open it", "From a prophet named Yāsīn in the surah", "From the town mentioned in its middle", "From a word meaning 'the heart'"], "The surah is named after the disjointed letters (al-ḥurūf al-muqaṭṭaʿa) Yā and Sīn in its first verse, like Ṭā Hā, Ṣād and Qāf."],
    de: ["Woher stammt der Name der Sūrat Yā Sīn?", ["Von den zwei Einzelbuchstaben am Anfang", "Von einem Propheten namens Yāsīn in der Sure", "Von der Stadt, die in ihrer Mitte erwähnt wird", "Von einem Wort mit der Bedeutung „das Herz“"], "Die Sure ist nach den Einzelbuchstaben (al-ḥurūf al-muqaṭṭaʿa) Yā und Sīn in ihrer ersten Āya benannt, wie auch Ṭā Hā, Ṣād und Qāf."],
    ar: ["من أين جاء اسم سورة يس؟", ["من الحرفين المقطعين في أولها", "من نبي اسمه ياسين ذُكر فيها", "من القرية المذكورة في وسطها", "من كلمة معناها القلب"], "سُمّيت السورة بالحرفين المقطّعين ياء وسين في أول آية منها، كما سُمّيت طه وص وق."] },

  { id: "tfs-007", s: "tafsir", g: 1, d: 2, t: ["al-rahman", "jinn-and-mankind"], src: "Ibn Kathīr, Tafsīr, on 55:13", v: "55:13",
    en: ["The refrain in the verse shown is addressed in the dual. To whom?", ["To the jinn and mankind", "To Mūsā and Hārūn", "To the two angels at the grave", "To Ādam and Ḥawwāʾ"], "The refrain of Sūrat al-Raḥmān asks the two 'weighty ones' (al-thaqalān), jinn and humans, which of their Lord's favours they would deny; the surah addresses both groups explicitly (e.g. 55:33)."],
    de: ["Der Kehrvers in der angezeigten Āya steht im Dual. Wer wird angesprochen?", ["Die Dschinn und die Menschen", "Mūsā und Hārūn", "Die beiden Engel im Grab", "Ādam und Ḥawwāʾ"], "Der Kehrvers der Sūrat ar-Raḥmān fragt die beiden „Gewichtigen“ (aṯ-ṯaqalān), Dschinn und Menschen, welche Wohltaten ihres Herrn sie leugnen wollen; die Sure spricht beide Gruppen ausdrücklich an (z. B. 55:33)."],
    ar: ["الخطاب في الآية المعروضة بصيغة المثنى، فلمن هو؟", ["للجن والإنس", "لموسى وهارون", "للملكين في القبر", "لآدم وحواء"], "اللازمة في سورة الرحمن خطاب للثقلين، الجن والإنس، عن أي نعم ربهما ينكرانها، وقد صرّحت السورة بخطابهما معًا كما في الآية الثالثة والثلاثين."] },

  { id: "tfs-008", s: "tafsir", g: 1, d: 1, t: ["al-mulk", "purpose-of-life"], src: "Ibn Kathīr, Tafsīr, on 67:2", v: "67:2",
    en: ["According to the verse shown, why did Allah create death and life?", ["To test who is best in deeds", "To show the passing of the seasons", "To let the angels record history", "To reward every soul in this world"], "Al-Mulk states that death and life were created as a trial, to show which of people is best in deed; the mufassirūn note it says 'best', not 'most', pointing to quality and sincerity."],
    de: ["Warum hat Allah nach der angezeigten Āya Tod und Leben erschaffen?", ["Um zu prüfen, wer die besten Taten verrichtet", "Um den Wechsel der Jahreszeiten zu zeigen", "Damit die Engel die Geschichte aufzeichnen", "Um jede Seele schon im Diesseits zu belohnen"], "Al-Mulk sagt, Tod und Leben seien als Prüfung erschaffen, um zu zeigen, wer die beste Tat verrichtet; die Kommentatoren betonen „die beste“, nicht „die meisten“, also Güte und Aufrichtigkeit."],
    ar: ["لماذا خلق الله الموت والحياة بحسب الآية المعروضة؟", ["لاختبار الناس في حسن أعمالهم", "ليُظهر تعاقب الفصول", "لتدوّن الملائكة التاريخ", "ليجزي كل نفس في الدنيا"], "خلق الله الموت والحياة اختبارًا يظهر به من هو الأفضل عملًا، ونبّه المفسرون إلى أن المعتبر الأحسن لا الأكثر، أي الإخلاص والإتقان."] },

  { id: "tfs-009", s: "tafsir", g: 1, d: 1, t: ["al-naba", "signs-in-creation"], src: "Ibn Kathīr, Tafsīr, on 78:6–7", v: "78:7",
    en: ["In the passage of the verse shown, the earth is described as a bed. How are the mountains described?", ["As pegs that hold it firm", "As walls that divide nations", "As thrones for the angels", "As rivers turned to stone"], "Al-Nabaʾ lists signs of Allah's power to prove the resurrection: the earth spread out like a bed and the mountains as pegs (awtād) that steady it."],
    de: ["Im Abschnitt der angezeigten Āya wird die Erde als Lager beschrieben. Wie werden die Berge beschrieben?", ["Als Pflöcke, die sie festigen", "Als Mauern zwischen den Völkern", "Als Throne für die Engel", "Als zu Stein gewordene Flüsse"], "Al-Nabaʾ zählt Zeichen der Macht Allahs als Beweis für die Auferstehung auf: die Erde als ausgebreitetes Lager und die Berge als Pflöcke (autād), die sie festigen."],
    ar: ["في سياق الآية المعروضة وُصفت الأرض بأنها مهاد، فبمَ وُصفت الجبال؟", ["بأنها أوتاد تثبّتها", "بأنها أسوار بين الأمم", "بأنها عروش للملائكة", "بأنها أنهار تحجّرت"], "تعدّد سورة النبأ آيات القدرة دليلًا على البعث: الأرض ممهدة كالفراش، والجبال كالأوتاد التي تثبّتها."] },

  { id: "tfs-010", s: "tafsir", g: 1, d: 2, t: ["abasa", "asbab-al-nuzul"], src: "Ibn Kathīr, Tafsīr, on 80:1–10", v: "80:2",
    en: ["Who is the blind man referred to at the start of Sūrat ʿAbasa?", ["ʿAbd Allāh ibn Umm Maktūm", "Bilāl ibn Rabāḥ", "ʿAmmār ibn Yāsir", "Abū Dharr al-Ghifārī"], "The mufassirūn report that Ibn Umm Maktūm came seeking instruction while the Prophet was busy inviting leaders of Quraysh; the surah teaches that the sincere seeker deserves attention."],
    de: ["Wer ist der blinde Mann am Anfang der Sūrat ʿAbasa?", ["ʿAbdullāh ibn Umm Maktūm", "Bilāl ibn Rabāḥ", "ʿAmmār ibn Yāsir", "Abū Ḏarr al-Ġifārī"], "Die Kommentatoren berichten, dass Ibn Umm Maktūm um Belehrung bat, während der Prophet die Führer der Quraisch einlud; die Sure lehrt, dass der aufrichtig Suchende Zuwendung verdient."],
    ar: ["مَن الأعمى المذكور في أول سورة عبس؟", ["عبد الله ابن أم مكتوم", "بلال بن رباح", "عمار بن ياسر", "أبو ذر الغفاري"], "ذكر المفسرون أن ابن أم مكتوم جاء يستعلم والنبي ﷺ مشغول بدعوة كبراء قريش، فبيّنت السورة أن طالب الهداية الصادق أولى بالإقبال عليه."] },

  { id: "tfs-011", s: "tafsir", g: 1, d: 1, t: ["al-takwir", "day-of-judgement"], src: "Ibn Kathīr, Tafsīr, on 81:1–14", v: "81:1",
    en: ["What is the main subject of the opening verses of Sūrat al-Takwīr, beginning with the verse shown?", ["The upheaval of the universe at the Last Day", "The creation of the heavens in six days", "The story of the People of the Cave", "The rules of fasting in Ramaḍān"], "Al-Takwīr opens with a series of scenes of the Hour: the sun wrapped up, the stars falling, the mountains moved, ending with every soul knowing what it has brought."],
    de: ["Worum geht es in den ersten Āyāt der Sūrat at-Takwīr, beginnend mit der angezeigten Āya?", ["Um die Erschütterung des Kosmos am Jüngsten Tag", "Um die Erschaffung der Himmel in sechs Tagen", "Um die Geschichte der Leute der Höhle", "Um die Regeln des Fastens im Ramaḍān"], "At-Takwīr beginnt mit einer Reihe von Szenen der Stunde: die Sonne wird eingerollt, die Sterne fallen, die Berge werden versetzt, bis jede Seele weiß, was sie mitgebracht hat."],
    ar: ["ما موضوع مطلع سورة التكوير الذي تبدأ به الآية المعروضة؟", ["انقلاب الكون عند قيام الساعة", "خلق السماوات في ستة أيام", "قصة أصحاب الكهف", "أحكام الصيام في رمضان"], "تفتتح سورة التكوير بمشاهد الساعة: تكوير الشمس وانكدار النجوم وتسيير الجبال، حتى تعلم كل نفس ما أحضرت."] },

  { id: "tfs-012", s: "tafsir", g: 1, d: 2, t: ["al-duha", "asbab-al-nuzul"], src: "Ibn Kathīr, Tafsīr, on 93:1–3; al-Bukhārī, Ṣaḥīḥ, Kitāb al-Tafsīr", v: "93:3",
    en: ["The verse shown was revealed after what?", ["A pause in revelation that the Prophet's enemies mocked", "The Prophet's victory at the Battle of Badr", "The death of the Prophet's son Ibrāhīm", "The return of the emigrants from Abyssinia"], "Al-Bukhārī reports that revelation paused for a time and a polytheist mocked the Prophet as abandoned; al-Ḍuḥā was revealed to assure him that his Lord had neither left him nor become displeased."],
    de: ["Nach welchem Ereignis wurde die angezeigte Āya offenbart?", ["Nach einer Pause der Offenbarung, über die Gegner spotteten", "Nach dem Sieg des Propheten bei Badr", "Nach dem Tod seines Sohnes Ibrāhīm", "Nach der Rückkehr der Auswanderer aus Abessinien"], "Al-Buḫārī berichtet, dass die Offenbarung eine Zeit lang ausblieb und ein Götzendiener spottete, der Prophet sei verlassen; aḍ-Ḍuḥā versicherte ihm, dass sein Herr ihn weder verlassen habe noch ihm zürne."],
    ar: ["بعد أيّ حدث نزلت الآية المعروضة؟", ["بعد فتور في الوحي سخر منه المشركون", "بعد انتصار النبي ﷺ في بدر", "بعد وفاة ابنه إبراهيم", "بعد عودة المهاجرين من الحبشة"], "روى البخاري أن الوحي فتر مدة فقال بعض المشركين إن صاحبه تركه، فنزلت سورة الضحى تطمئن النبي ﷺ أن ربه لم يتركه ولم يبغضه."] },

  { id: "tfs-013", s: "tafsir", g: 1, d: 1, t: ["al-sharh", "hope-and-patience"], src: "Ibn Kathīr, Tafsīr, on 94:5–6", v: "94:6",
    en: ["What is the central message of the verse shown and the one before it?", ["Ease accompanies hardship", "Wealth is a sign of Allah's pleasure", "Hardship is a punishment for sin", "Patience is only needed in war"], "Al-Sharḥ repeats that with hardship comes ease. The mufassirūn observe that 'hardship' is definite and 'ease' indefinite, so one hardship is met by more than one ease."],
    de: ["Was ist die Kernaussage der angezeigten Āya und der vorherigen?", ["Mit der Erschwernis kommt Erleichterung", "Reichtum ist ein Zeichen von Allahs Wohlgefallen", "Erschwernis ist immer Strafe für Sünde", "Geduld braucht man nur im Krieg"], "Aš-Šarḥ wiederholt, dass mit der Erschwernis Erleichterung kommt. Die Kommentatoren bemerken, dass „Erschwernis“ bestimmt und „Erleichterung“ unbestimmt steht: Einer Erschwernis stehen mehr als eine Erleichterung gegenüber."],
    ar: ["ما المعنى الرئيس في الآية المعروضة والتي قبلها؟", ["أن اليسر يصاحب العسر", "أن الغنى علامة رضا الله", "أن العسر عقوبة على الذنب دائمًا", "أن الصبر لا يُحتاج إليه إلا في الحرب"], "تكرّر سورة الشرح أن اليسر يصحب العسر، ونبّه المفسرون إلى أن لفظ العسر جاء معرّفًا واليسر منكّرًا، فالعسر الواحد يقابله يسران."] },

  { id: "tfs-014", s: "tafsir", g: 1, d: 1, t: ["al-alaq", "first-revelation"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb Badʾ al-Waḥy", v: "96:1",
    en: ["What is special about the verse shown and the four after it?", ["They are the first verses of the Quran revealed", "They are the last verses of the Quran revealed", "They were revealed in Madīna after the Hijra", "They were revealed during the Night Journey"], "According to the hadith of ʿĀʾisha in Ṣaḥīḥ al-Bukhārī, the first revelation in the cave of Ḥirāʾ was the opening five verses of al-ʿAlaq, beginning with the command to read."],
    de: ["Was ist das Besondere an der angezeigten Āya und den vier folgenden?", ["Sie sind die ersten offenbarten Āyāt des Korans", "Sie sind die letzten offenbarten Āyāt des Korans", "Sie wurden nach der Hiǧra in Medina offenbart", "Sie wurden während der Nachtreise offenbart"], "Nach dem Hadith ʿĀʾišas in Ṣaḥīḥ al-Buḫārī waren die ersten fünf Āyāt von al-ʿAlaq mit dem Befehl zu lesen die erste Offenbarung in der Höhle Ḥirāʾ."],
    ar: ["ما الذي يميّز الآية المعروضة والآيات الأربع بعدها؟", ["أنها أول ما نزل من القرآن", "أنها آخر ما نزل من القرآن", "أنها نزلت في المدينة بعد الهجرة", "أنها نزلت ليلة الإسراء"], "في حديث عائشة في صحيح البخاري أن أول ما نزل في غار حراء الآيات الخمس الأولى من سورة العلق المبتدئة بالأمر بالقراءة."] },

  { id: "tfs-015", s: "tafsir", g: 1, d: 1, t: ["al-qadr", "laylat-al-qadr"], src: "Ibn Kathīr, Tafsīr, on 97:1–3", v: "97:3",
    en: ["According to the verse shown, the Night of Decree is better than what?", ["A thousand months", "A hundred years", "Seventy nights of prayer", "The whole month of Ramaḍān"], "Sūrat al-Qadr states that this night, in which the Quran was sent down, is better than a thousand months; the mufassirūn explain that worship in it surpasses worship in a thousand months without it."],
    de: ["Besser als was ist die Nacht der Bestimmung nach der angezeigten Āya?", ["Als tausend Monate", "Als hundert Jahre", "Als siebzig Gebetsnächte", "Als der ganze Monat Ramaḍān"], "Sūrat al-Qadr sagt, diese Nacht, in der der Koran herabgesandt wurde, sei besser als tausend Monate; die Kommentatoren erklären, der Gottesdienst in ihr übertreffe den von tausend Monaten ohne sie."],
    ar: ["ليلة القدر خير من ماذا بحسب الآية المعروضة؟", ["من ألف شهر", "من مئة سنة", "من سبعين ليلة قيام", "من شهر رمضان كله"], "تقرّر سورة القدر تفضيل هذه الليلة التي أُنزل فيها القرآن على ألف شهر، وفسّره العلماء بأن العمل فيها خير من العمل في ألف شهر ليس فيها ليلة القدر."] },

  { id: "tfs-016", s: "tafsir", g: 1, d: 1, t: ["al-zalzala", "accountability"], src: "Ibn Kathīr, Tafsīr, on 99:7–8", v: "99:7",
    en: ["What does the verse shown and the one after it teach?", ["Even the smallest good or evil deed will be seen", "Only major sins are recorded", "Good deeds wipe out the need for repentance", "Deeds are judged by their size alone"], "The close of al-Zalzala says that whoever does an atom's weight (mithqāl dharra) of good or evil will see it, so no deed is too small to count."],
    de: ["Was lehren die angezeigte Āya und die folgende?", ["Selbst die kleinste gute oder böse Tat wird gesehen", "Nur große Sünden werden aufgezeichnet", "Gute Taten machen Reue überflüssig", "Taten werden nur nach ihrer Größe beurteilt"], "Der Schluss von az-Zalzala sagt: Wer das Gewicht eines Stäubchens (miṯqāl ḏarra) Gutes oder Böses tut, wird es sehen; keine Tat ist zu klein, um zu zählen."],
    ar: ["ماذا تعلّم الآية المعروضة والتي بعدها؟", ["أن أصغر عمل من خير أو شر سيُرى", "أن الكبائر وحدها هي التي تُكتب", "أن الحسنات تغني عن التوبة", "أن الأعمال تُوزن بحجمها فقط"], "تختم سورة الزلزلة بأن العامل سيرى عمله ولو كان بوزن الذرة من خير أو شر، فلا يُستهان بعمل مهما صغر."] },

  { id: "tfs-017", s: "tafsir", g: 1, d: 2, t: ["al-asr", "surah-themes"], src: "Ibn Kathīr, Tafsīr, on Sūrat al-ʿAṣr", v: "103:3",
    en: ["The verse shown names those who are exempt from loss. Which group of qualities does it list?", ["Faith, good deeds, urging truth and urging patience", "Prayer, fasting, charity and pilgrimage", "Knowledge, wealth, lineage and strength", "Patience, gratitude, modesty and generosity"], "Al-ʿAṣr says all people are in loss except those who believe, do righteous deeds, and urge one another to the truth and to patience: two qualities perfect oneself and two perfect others."],
    de: ["Die angezeigte Āya nennt die Ausnahme vom Verlust. Welche Eigenschaften zählt sie auf?", ["Glauben, gute Taten, gegenseitiges Mahnen zur Wahrheit und zur Geduld", "Gebet, Fasten, Almosen und Pilgerfahrt", "Wissen, Reichtum, Abstammung und Stärke", "Geduld, Dankbarkeit, Bescheidenheit und Großzügigkeit"], "Al-ʿAṣr sagt, alle Menschen seien im Verlust außer denen, die glauben, gute Werke tun und einander zur Wahrheit und zur Geduld ermahnen: zwei Eigenschaften vervollkommnen einen selbst, zwei die anderen."],
    ar: ["تستثني الآية المعروضة قومًا من الخسران، فما الصفات التي ذكرتها؟", ["الإيمان والعمل الصالح والتواصي بالحق والصبر", "الصلاة والصيام والزكاة وحج البيت الحرام", "العلم والمال وشرف النسب وقوة البدن", "الصبر والشكر والحياء والجود بالمال"], "تقرر سورة العصر أن الإنسان خاسر إلا المؤمنين العاملين للصالحات الذين يوصي بعضهم بعضًا بالحق والصبر؛ فالأوليان تكميل للنفس، والأخريان تكميل للغير."] },

  { id: "tfs-018", s: "tafsir", g: 1, d: 2, t: ["al-kawthar", "hadith-in-tafsir"], src: "Muslim, Ṣaḥīḥ, Kitāb al-Ṣalāh (hadith of Anas on al-Kawthar)", v: "108:1",
    en: ["According to the hadith of Anas in Ṣaḥīḥ Muslim, what is al-Kawthar in the verse shown?", ["A river in Paradise promised to the Prophet", "The well of Zamzam in Makka", "The conquest of Makka", "The night of the Prophet's ascension"], "In Ṣaḥīḥ Muslim the Prophet, after this surah was revealed, explained that al-Kawthar is a river his Lord promised him in Paradise. Ibn ʿAbbās described it as the abundant good, which includes that river."],
    de: ["Was ist al-Kauṯar in der angezeigten Āya nach dem Hadith von Anas in Ṣaḥīḥ Muslim?", ["Ein dem Propheten versprochener Paradiesfluss", "Der gesegnete Brunnen Zamzam in Mekka", "Die siegreiche Eroberung Mekkas", "Die Nacht der Himmelfahrt des Propheten"], "In Ṣaḥīḥ Muslim erklärt der Prophet nach der Offenbarung dieser Sure, al-Kauṯar sei ein Fluss, den sein Herr ihm im Paradies versprochen habe. Ibn ʿAbbās beschrieb es als das reichliche Gute, das diesen Fluss einschließt."],
    ar: ["ما الكوثر في الآية المعروضة بحسب حديث أنس في صحيح مسلم؟", ["نهر في الجنة وعده الله نبيه", "بئر زمزم المباركة في مكة", "فتح مكة ودخول الناس في الدين", "ليلة المعراج إلى السماء"], "في صحيح مسلم أن النبي ﷺ لما نزلت السورة بيّن أن الكوثر نهر وعده إياه ربه في الجنة، وفسّره ابن عباس بالخير الكثير الذي يدخل فيه ذلك النهر."] },

  { id: "tfs-019", s: "tafsir", g: 1, d: 1, t: ["al-kafirun", "surah-themes"], src: "Ibn Kathīr, Tafsīr, on Sūrat al-Kāfirūn", v: "109:6",
    en: ["What is the main theme of Sūrat al-Kāfirūn, which closes with the verse shown?", ["Clear disavowal of the polytheists' worship", "Permission to fight the polytheists", "The story of the Prophet's migration", "Rules of trade with non-Muslims"], "Al-Kāfirūn declares a complete separation in worship: the Prophet does not worship what they worship. Ibn Kathīr calls it the surah of disavowal (barāʾa) from shirk."],
    de: ["Was ist das Hauptthema der Sūrat al-Kāfirūn, die mit der angezeigten Āya endet?", ["Klare Lossagung von der Anbetung der Götzendiener", "Erlaubnis zum Kampf gegen die Götzendiener", "Die Geschichte der Auswanderung des Propheten", "Regeln des Handels mit Nichtmuslimen"], "Al-Kāfirūn erklärt eine vollständige Trennung im Gottesdienst: Der Prophet betet nicht an, was sie anbeten. Ibn Kaṯīr nennt sie die Sure der Lossagung (barāʾa) vom Schirk."],
    ar: ["ما الموضوع الرئيس لسورة الكافرون التي تُختم بالآية المعروضة؟", ["البراءة الواضحة من عبادة المشركين", "الإذن بقتال المشركين", "قصة هجرة النبي ﷺ", "أحكام التجارة مع غير المسلمين"], "تعلن سورة الكافرون المفاصلة التامة في العبادة، فالنبي ﷺ لا يشاركهم في عبادة آلهتهم، وسمّاها ابن كثير سورة البراءة من الشرك."] },

  { id: "tfs-020", s: "tafsir", g: 1, d: 1, t: ["al-ikhlas", "tawhid"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb Faḍāʾil al-Qurʾān", v: "112:1",
    en: ["According to the hadith in Ṣaḥīḥ al-Bukhārī, Sūrat al-Ikhlāṣ, beginning with the verse shown, equals what?", ["A third of the Quran", "Half of the Quran", "A quarter of the Quran", "The whole of al-Baqara"], "The Prophet said that this surah equals a third of the Quran. Scholars explain that the Quran deals with rulings, narratives and tawḥīd, and al-Ikhlāṣ is pure tawḥīd."],
    de: ["Wem entspricht die Sūrat al-Iḫlāṣ, die mit der angezeigten Āya beginnt, nach dem Hadith in Ṣaḥīḥ al-Buḫārī?", ["Einem Drittel des Korans", "Der Hälfte des Korans", "Einem Viertel des Korans", "Der ganzen Sūrat al-Baqara"], "Der Prophet sagte, diese Sure entspreche einem Drittel des Korans. Die Gelehrten erklären: Der Koran behandelt Rechtsbestimmungen, Erzählungen und Tauḥīd, und al-Iḫlāṣ ist reiner Tauḥīd."],
    ar: ["سورة الإخلاص المبتدئة بالآية المعروضة تعدل ماذا بحسب حديث صحيح البخاري؟", ["ثلث القرآن", "نصف القرآن", "ربع القرآن", "سورة البقرة كاملة"], "أخبر النبي ﷺ أنها تعدل ثلث القرآن، وبيّن العلماء أن القرآن أحكام وقصص وتوحيد، وسورة الإخلاص توحيد خالص."] },

  { id: "tfs-021", s: "tafsir", g: 1, d: 1, t: ["muawwidhatan", "surah-names"], src: "Ibn Kathīr, Tafsīr, on Sūrat al-Falaq and al-Nās", v: "113:1",
    en: ["Sūrat al-Falaq, beginning with the verse shown, and Sūrat al-Nās are together called al-Muʿawwidhatān. What does this name mean?", ["The two surahs of seeking refuge", "The two surahs of praise", "The two surahs of repentance", "The two surahs of the night"], "Both surahs begin with the command to seek refuge with Allah, hence 'the two refuge-givers'. The Prophet used to recite them for protection."],
    de: ["Sūrat al-Falaq, die mit der angezeigten Āya beginnt, und Sūrat an-Nās heißen zusammen al-Muʿawwiḏatān. Was bedeutet der Name?", ["Die beiden Suren der Zufluchtnahme", "Die beiden Suren des Lobpreises", "Die beiden Suren der Reue", "Die beiden Suren der Nacht"], "Beide Suren beginnen mit dem Befehl, bei Allah Zuflucht zu suchen, daher „die beiden Zuflucht gebenden“. Der Prophet rezitierte sie zum Schutz."],
    ar: ["سورة الفلق المبتدئة بالآية المعروضة وسورة الناس تُسمّيان المعوّذتين، فما معنى الاسم؟", ["السورتان اللتان يُستعاذ بهما", "السورتان اللتان يُحمد بهما الله", "السورتان اللتان تُقرآن عند التوبة", "السورتان اللتان تُقرآن في الليل"], "تبدأ كلتاهما بالأمر بالاستعاذة بالله، فسُمّيتا المعوّذتين، وكان النبي ﷺ يتعوّذ بهما."] },

  { id: "tfs-022", s: "tafsir", g: 1, d: 2, t: ["al-nur", "light-verse"], src: "Ibn Kathīr, Tafsīr, on 24:35", v: "24:35",
    en: ["The verse shown is known as the Light Verse (āyat al-nūr). Which image does its parable use?", ["A lamp in a niche, set inside a glass", "A full moon rising over a dark sea", "A fire kindled by travellers in the desert", "Lightning flashing through heavy clouds"], "The verse likens Allah's light to a niche (mishkāt) holding a lamp inside a glass like a brilliant star, lit from the oil of a blessed olive tree. Fire in the desert and lightning appear in other parables (e.g. 2:17–19)."],
    de: ["Die angezeigte Āya heißt Lichtvers (āyat an-nūr). Welches Bild verwendet ihr Gleichnis?", ["Eine Lampe in einer Nische, in einem Glas", "Ein Vollmond, der über einem dunklen Meer aufgeht", "Ein Feuer, das Reisende in der Wüste entzünden", "Ein Blitz, der durch schwere Wolken zuckt"], "Die Āya vergleicht Allahs Licht mit einer Nische (miškāt), in der eine Lampe in einem Glas wie ein funkelnder Stern brennt, gespeist vom Öl eines gesegneten Ölbaums. Feuer und Blitz stehen in anderen Gleichnissen (z. B. 2:17–19)."],
    ar: ["الآية المعروضة تُعرف بآية النور. ما الصورة التي يستعملها مثلها؟", ["سراج في كوّة داخل زجاج صافٍ", "بدر يطلع على بحر مظلم", "نار يوقدها مسافرون في الصحراء", "برق يلمع بين سحاب كثيف"], "شبّهت الآية نور الله بكوّة فيها سراج داخل زجاج صافٍ يلمع كالنجم، يُشعل من زيت شجرة زيتون مباركة، أما النار والبرق ففي أمثال أخرى كما في أوائل البقرة."] },

  // ---------- stage 2 ----------
  { id: "tfs-023", s: "tafsir", g: 2, d: 3, t: ["al-kahf", "people-of-the-cave"], src: "Ibn Kathīr, Tafsīr, on 18:22", v: "18:22",
    en: ["The verse shown mentions different claims about the number of the youths of the cave. What guidance does it give about this?", ["Leave the matter to Allah and do not argue about it at length", "Accept the number given by the People of the Book", "Count them as three, the first number mentioned", "Search for their cave to settle the question"], "The verse reports three guesses, says that their exact number is known to Allah and only a few, and forbids lengthy dispute about it. Ibn ʿAbbās is reported to have said he was among the few and that they were seven."],
    de: ["Die angezeigte Āya erwähnt verschiedene Angaben zur Zahl der Jünglinge der Höhle. Welche Anleitung gibt sie dazu?", ["Die Sache Allah überlassen und nicht lange streiten", "Die Zahl der Leute der Schrift übernehmen", "Sie als drei zählen, die zuerst genannte Zahl", "Ihre Höhle suchen, um die Frage zu klären"], "Die Āya nennt drei Vermutungen, sagt, dass ihre genaue Zahl Allah und nur wenige kennen, und verbietet langen Streit darüber. Von Ibn ʿAbbās wird überliefert, er gehöre zu diesen wenigen; es seien sieben gewesen."],
    ar: ["تذكر الآية المعروضة أقوالًا في عدد أصحاب الكهف، فما توجيهها في ذلك؟", ["ردّ العلم إلى الله وترك الجدال الطويل فيه", "الأخذ بالعدد الذي يقوله أهل الكتاب", "اعتماد العدد ثلاثة لأنه ذُكر أولًا", "البحث عن الكهف لحسم المسألة"], "ذكرت الآية ثلاثة أقوال، وبيّنت أن العلم بعددهم عند الله وقليل من الناس، ونهت عن الجدال الطويل فيهم. ورُوي عن ابن عباس أنه قال: أنا من ذلك القليل، كانوا سبعة."] },

  { id: "tfs-024", s: "tafsir", g: 2, d: 2, t: ["al-kahf", "etiquette"], src: "Ibn Kathīr, Tafsīr, on 18:23–24", v: "18:23",
    en: ["What etiquette do the verse shown and the one after it teach?", ["To make future plans conditional on Allah's will", "To write down every promise one makes", "To swear an oath before every journey", "To consult a scholar before every decision"], "The believer should not say he will certainly do something tomorrow without adding 'if Allah wills' (in shāʾ Allāh), and if he forgets, he should remember his Lord. Ibn Kathīr links the verses to the delay in revelation after the Prophet promised an answer without saying it."],
    de: ["Welche Umgangsform lehren die angezeigte Āya und die folgende?", ["Künftige Vorhaben an Allahs Willen zu knüpfen", "Jedes Versprechen schriftlich festzuhalten", "Vor jeder Reise einen Eid zu schwören", "Vor jeder Entscheidung einen Gelehrten zu fragen"], "Der Gläubige soll nicht sagen, er werde etwas morgen sicher tun, ohne „so Allah will“ (in šāʾa Allāh) hinzuzufügen; vergisst er es, soll er seines Herrn gedenken. Ibn Kaṯīr verbindet die Āyāt mit dem Ausbleiben der Offenbarung, nachdem der Prophet eine Antwort ohne diesen Zusatz versprochen hatte."],
    ar: ["ما الأدب الذي تعلّمه الآية المعروضة والتي بعدها؟", ["تعليق العزم على المستقبل بمشيئة الله", "كتابة كل وعد يقطعه المرء", "الحلف قبل كل سفر", "استشارة عالم قبل كل قرار"], "لا يجزم المؤمن بأنه فاعل شيئًا غدًا دون أن يقول إن شاء الله، فإن نسي ذكر ربه. وربط ابن كثير الآيتين بتأخر الوحي حين وعد النبي ﷺ بالجواب دون استثناء."] },

  { id: "tfs-025", s: "tafsir", g: 2, d: 2, t: ["al-kahf", "two-gardens"], src: "Ibn Kathīr, Tafsīr, on 18:32–44", v: "18:35",
    en: ["In the parable of the two gardens, what was the wrong of the garden owner shown in the verse?", ["He thought his garden would last forever and doubted the Hour", "He withheld his workers' wages and mistreated them", "He built his garden on land taken unjustly from orphans", "He worshipped idols that he set up among his palms"], "Entering his garden proud and wronging himself, he claimed it would never perish and doubted that the Hour would come; his believing companion warned him, and the garden was destroyed."],
    de: ["Worin bestand im Gleichnis der zwei Gärten das Unrecht des Gartenbesitzers in der angezeigten Āya?", ["Er hielt seinen Garten für ewig und bezweifelte die Stunde", "Er enthielt seinen Arbeitern den Lohn vor und misshandelte sie", "Er legte seinen Garten auf Land an, das er Waisen geraubt hatte", "Er betete Götzen an, die er zwischen seinen Palmen aufstellte"], "Hochmütig betrat er seinen Garten und tat sich selbst Unrecht: Er behauptete, dieser werde nie vergehen, und bezweifelte das Kommen der Stunde; sein gläubiger Gefährte warnte ihn, und der Garten wurde vernichtet."],
    ar: ["في مثل صاحب الجنتين، ما الذي ظلم به نفسه في الآية المعروضة؟", ["ظنّ أن جنته لا تفنى وشكّ في قيام الساعة", "منع عمّاله أجورهم وأساء معاملتهم", "أقام جنته على أرض اغتصبها من الأيتام", "عبد أصنامًا نصبها بين نخيله"], "دخل جنته متكبرًا ظالمًا لنفسه فزعم أنها لن تهلك وشكّ في قيام الساعة، فوعظه صاحبه المؤمن، ثم أُهلكت جنته."] },

  { id: "tfs-026", s: "tafsir", g: 2, d: 2, t: ["al-kahf", "musa-and-khidr"], src: "Ibn Kathīr, Tafsīr, on 18:65–82", v: "18:71",
    en: ["The verse shown begins the journey of Mūsā with al-Khiḍr. Which event is NOT one of its three incidents?", ["Splitting a rock so that springs gushed out", "Making a hole in a boat", "Killing a young boy", "Repairing a wall about to collapse"], "The three incidents are the boat, the boy and the wall, each explained at the end by al-Khiḍr. Water gushing from a rock struck by Mūsā's staff belongs to the story of the Children of Israel (2:60)."],
    de: ["Die angezeigte Āya beginnt die Reise Mūsās mit al-Ḫiḍr. Welches Ereignis gehört NICHT zu ihren drei Begebenheiten?", ["Einen Felsen spalten, sodass Quellen sprudelten", "Ein Loch in ein Boot schlagen", "Einen Jungen töten", "Eine einstürzende Mauer aufrichten"], "Die drei Begebenheiten sind das Boot, der Junge und die Mauer, die al-Ḫiḍr am Ende erklärt. Wasser aus dem Felsen, den Mūsā mit dem Stab schlug, gehört zur Geschichte der Kinder Israels (2:60)."],
    ar: ["تبدأ الآية المعروضة رحلة موسى مع الخضر. أيّ هذه ليس من الوقائع الثلاث فيها؟", ["ضرب صخرة فتفجّرت منها العيون", "خرق السفينة", "قتل الغلام", "إقامة الجدار الذي كاد ينقض"], "الوقائع الثلاث: السفينة والغلام والجدار، وقد فسّرها الخضر في آخر القصة. أما تفجّر الماء من الحجر بعصا موسى ففي قصة بني إسرائيل في سورة البقرة."] },

  { id: "tfs-027", s: "tafsir", g: 2, d: 2, t: ["al-kahf", "musa-and-khidr"], src: "Ibn Kathīr, Tafsīr, on 18:79", v: "18:79",
    en: ["Why did al-Khiḍr damage the boat, according to the verse shown?", ["A king was seizing every sound boat by force", "The boat belonged to thieves", "The boat was about to sink in a storm", "The owners had refused to carry them"], "The boat belonged to poor people who worked at sea; ahead of them was a king who took every good boat by force, so a defect saved it for its owners."],
    de: ["Warum beschädigte al-Ḫiḍr das Boot nach der angezeigten Āya?", ["Ein König nahm jedes intakte Boot mit Gewalt", "Das Boot gehörte Dieben", "Das Boot drohte im Sturm zu sinken", "Die Besitzer hatten sich geweigert, sie mitzunehmen"], "Das Boot gehörte Armen, die auf dem Meer arbeiteten; vor ihnen war ein König, der jedes gute Boot gewaltsam nahm, sodass ein Schaden es seinen Besitzern erhielt."],
    ar: ["لماذا خرق الخضر السفينة بحسب الآية المعروضة؟", ["لأن ملكًا كان يأخذ كل سفينة سليمة غصبًا", "لأنها كانت لقوم لصوص", "لأنها كانت ستغرق في عاصفة", "لأن أصحابها رفضوا حملهما"], "كانت السفينة لمساكين يعملون في البحر، وكان أمامهم ملك يغتصب كل سفينة صالحة، فكان العيب سببًا في بقائها لأصحابها."] },

  { id: "tfs-028", s: "tafsir", g: 2, d: 3, t: ["al-kahf", "musa-and-khidr"], src: "Ibn Kathīr, Tafsīr, on 18:82", v: "18:82",
    en: ["According to the verse shown, why was the wall repaired?", ["It hid a treasure of two orphans whose father was righteous", "It protected the town from an approaching army", "It was part of a mosque built by a prophet", "Its owner had paid al-Khiḍr to repair it"], "The wall belonged to two orphan boys in the town, beneath it was a treasure for them, and their father had been righteous; Allah willed that they reach maturity and take out their treasure. The mufassirūn draw from it that a parent's righteousness benefits the children."],
    de: ["Warum wurde die Mauer nach der angezeigten Āya wieder aufgerichtet?", ["Darunter lag der Schatz zweier Waisen eines frommen Vaters", "Sie schützte die Stadt vor einem nahenden Heer", "Sie gehörte zu einer von einem Propheten erbauten Moschee", "Ihr Besitzer hatte al-Ḫiḍr dafür im Voraus bezahlt"], "Die Mauer gehörte zwei Waisenjungen in der Stadt, darunter lag ein Schatz für sie, und ihr Vater war rechtschaffen; Allah wollte, dass sie mündig werden und ihren Schatz heben. Die Kommentatoren folgern, dass die Rechtschaffenheit der Eltern den Kindern nützt."],
    ar: ["لماذا أُقيم الجدار بحسب الآية المعروضة؟", ["لأن تحته كنزًا ليتيمين كان أبوهما صالحًا", "لأنه كان يحمي القرية من جيش قادم", "لأنه كان جزءًا من مسجد بناه نبي", "لأن صاحبه دفع للخضر أجرًا"], "كان الجدار ليتيمين في المدينة وتحته كنز لهما وكان أبوهما صالحًا، فأراد الله أن يبلغا رشدهما ويستخرجا كنزهما. واستنبط المفسرون أن صلاح الآباء ينفع الأبناء."] },

  { id: "tfs-029", s: "tafsir", g: 2, d: 2, t: ["al-kahf", "dhul-qarnayn"], src: "Ibn Kathīr, Tafsīr, on 18:94–97", v: "18:94",
    en: ["What did the people in the verse shown ask Dhū al-Qarnayn to do?", ["To build a barrier between them and Yaʾjūj and Maʾjūj", "To lead their army on a march to the rising sun", "To rule over them as their king for the rest of his life", "To teach them the religion of Ibrāhīm and build a temple"], "They complained that Yaʾjūj and Maʾjūj were spreading corruption and offered payment for a barrier; he declined the payment, asked for their labour, and built a wall of iron with molten copper."],
    de: ["Worum baten die Leute in der angezeigten Āya Ḏū al-Qarnain?", ["Einen Damm zwischen ihnen und Yaʾǧūǧ und Maʾǧūǧ zu bauen", "Ihr Heer auf einem Zug zum Sonnenaufgang anzuführen", "Für den Rest seines Lebens als ihr König zu herrschen", "Sie die Religion Ibrāhīms zu lehren und einen Tempel zu bauen"], "Sie klagten, dass Yaʾǧūǧ und Maʾǧūǧ Unheil stifteten, und boten Bezahlung für einen Damm an; er lehnte das Geld ab, verlangte ihre Mithilfe und baute einen Wall aus Eisen mit geschmolzenem Kupfer."],
    ar: ["ماذا طلب القوم من ذي القرنين في الآية المعروضة؟", ["أن يبني سدًا بينهم وبين يأجوج ومأجوج", "أن يقود جيشهم في مسيرة إلى مطلع الشمس", "أن يكون ملكًا عليهم ما بقي من عمره", "أن يعلّمهم ملة إبراهيم ويبني لهم معبدًا"], "شكوا إفساد يأجوج ومأجوج وعرضوا عليه مالًا ليبني سدًا، فأبى المال وطلب عونهم بالعمل، وبنى ردمًا من الحديد أفرغ عليه النحاس المذاب."] },

  { id: "tfs-030", s: "tafsir", g: 2, d: 2, t: ["maryam", "zakariyya-and-yahya"], src: "Ibn Kathīr, Tafsīr, on 19:2–11", v: "19:7",
    en: ["What does the verse shown say about the name of Yaḥyā?", ["No one had been given this name before him", "It was chosen by his father Zakariyyā", "It was the name of his grandfather", "It was given to him by the people of the Temple"], "In answer to Zakariyyā's prayer, Allah gave him the good news of a son named Yaḥyā and stated that no one before had been given this name; some early mufassirūn also read it as 'no one like him'."],
    de: ["Was sagt die angezeigte Āya über den Namen Yaḥyās?", ["Niemand vor ihm hatte diesen Namen erhalten", "Sein Vater Zakariyyā hatte ihn gewählt", "Es war der Name seines Großvaters", "Die Leute des Tempels gaben ihn ihm"], "Als Antwort auf Zakariyyās Bittgebet verkündete Allah ihm einen Sohn namens Yaḥyā und sagte, niemand vor ihm habe diesen Namen getragen; einige frühe Kommentatoren deuteten es auch als „niemand wie er“."],
    ar: ["ماذا تقول الآية المعروضة عن اسم يحيى؟", ["أنه لم يُسمَّ به أحد قبله", "أن أباه زكريا هو الذي اختاره", "أنه اسم جدّه", "أن أهل الهيكل سمّوه به"], "استجاب الله دعاء زكريا فبشّره بغلام اسمه يحيى، وأخبر أنه لم يُجعل هذا الاسم لأحد من قبل، وفسّره بعض السلف بأنه لا شبيه له."] },

  { id: "tfs-031", s: "tafsir", g: 2, d: 3, t: ["maryam", "ibrahim", "dawah"], src: "Ibn Kathīr, Tafsīr, on 19:41–48", v: "19:42",
    en: ["What characterises Ibrāhīm's speech to his father in the verse shown and those after it?", ["Gentle, respectful address while firmly rejecting idols", "Harsh rebuke followed by breaking the idols at home", "Silence and leaving without explanation", "Agreement to worship the idols on festivals"], "Ibrāhīm repeatedly addresses his father tenderly and asks why he worships what neither hears nor sees; even when threatened, he answers with a greeting of peace and a promise to seek forgiveness for him. The mufassirūn cite it as a model of gentle daʿwa to parents."],
    de: ["Was kennzeichnet Ibrāhīms Rede an seinen Vater in der angezeigten Āya und den folgenden?", ["Sanfte, respektvolle Anrede bei klarer Ablehnung der Götzen", "Harter Tadel und Zerschlagen der Götzen im Haus", "Schweigen und Weggehen ohne Erklärung", "Zustimmung, die Götzen an Festtagen anzubeten"], "Ibrāhīm spricht seinen Vater immer wieder liebevoll an und fragt, warum er anbetet, was weder hört noch sieht; selbst bedroht antwortet er mit einem Friedensgruß und dem Versprechen, für ihn um Vergebung zu bitten. Die Kommentatoren sehen darin ein Vorbild sanfter Einladung gegenüber Eltern."],
    ar: ["ما الذي يميّز خطاب إبراهيم لأبيه في الآية المعروضة وما بعدها؟", ["التلطف والأدب مع الحزم في رفض الأصنام", "التعنيف ثم تكسير الأصنام في البيت", "السكوت والانصراف دون بيان", "الموافقة على عبادة الأصنام في الأعياد"], "يخاطب إبراهيم أباه مرارًا بلطف ويسأله لماذا يعبد ما لا سمع له ولا بصر، وحين هدّده ردّ عليه بالسلام ووعده بالاستغفار له. ويجعله المفسرون مثالًا في دعوة الوالدين بالرفق."] },

  { id: "tfs-032", s: "tafsir", g: 2, d: 2, t: ["ta-ha", "musa", "dua"], src: "Ibn Kathīr, Tafsīr, on 20:25–32", v: "20:27",
    en: ["In his prayer before going to Firʿawn, what does Mūsā ask for in the verse shown?", ["That the knot be loosened from his tongue", "That his staff be turned into a serpent", "That Firʿawn be destroyed at once", "That he be given a large army"], "Mūsā asked for an expanded chest, an eased task and the untying of a knot in his tongue so that his speech would be understood, and asked that Hārūn be made his helper."],
    de: ["Worum bittet Mūsā in der angezeigten Āya vor seinem Gang zu Firʿawn?", ["Dass der Knoten seiner Zunge gelöst werde", "Dass sein Stab zur Schlange werde", "Dass Firʿawn sofort vernichtet werde", "Dass ihm ein großes Heer gegeben werde"], "Mūsā bat um eine geweitete Brust, eine erleichterte Aufgabe und das Lösen eines Knotens seiner Zunge, damit man seine Rede verstehe, und darum, Hārūn zu seinem Helfer zu machen."],
    ar: ["بماذا دعا موسى في الآية المعروضة قبل ذهابه إلى فرعون؟", ["أن يزيل الله عقدة لسانه", "أن تصير عصاه حية", "أن يُهلك فرعون فورًا", "أن يُعطى جيشًا كبيرًا"], "سأل موسى انشراح الصدر وتيسير الأمر وإزالة ما في لسانه من عقدة ليُفهم كلامه، وسأل أن يكون هارون وزيرًا له."] },

  { id: "tfs-033", s: "tafsir", g: 2, d: 2, t: ["ta-ha", "musa", "dawah"], src: "Ibn Kathīr, Tafsīr, on 20:43–44", v: "20:44",
    en: ["How were Mūsā and Hārūn told to speak to Firʿawn in the verse shown?", ["With gentle words, that he might reflect or fear", "With threats, so that he would submit quickly", "Only through written letters", "In the presence of the whole army"], "Although Firʿawn was a tyrant, they were told to speak to him gently, in the hope that he would take heed or fear. The mufassirūn draw from it that gentleness is the rule in calling even the arrogant."],
    de: ["Wie sollten Mūsā und Hārūn in der angezeigten Āya mit Firʿawn reden?", ["Mit sanften Worten, damit er nachdenke oder sich fürchte", "Mit Drohungen, damit er sich schnell füge", "Nur durch geschriebene Briefe", "Vor dem ganzen Heer"], "Obwohl Firʿawn ein Tyrann war, sollten sie sanft mit ihm reden, in der Hoffnung, dass er sich ermahnen lasse oder fürchte. Die Kommentatoren folgern daraus, dass Milde auch gegenüber Hochmütigen die Regel der Einladung ist."],
    ar: ["كيف أُمر موسى وهارون أن يخاطبا فرعون في الآية المعروضة؟", ["بكلام رفيق رجاء أن يتعظ أو يخاف", "بالتهديد ليخضع سريعًا", "برسائل مكتوبة فقط", "أمام جيشه كله"], "مع طغيان فرعون أُمرا بأن يكلّماه برفق رجاء أن يتعظ أو يخاف، واستنبط المفسرون أن الرفق أصل في دعوة المتكبرين أيضًا."] },

  { id: "tfs-034", s: "tafsir", g: 2, d: 2, t: ["al-nur", "ifk-incident"], src: "Ibn Kathīr, Tafsīr, on 24:11–26; al-Bukhārī, Ṣaḥīḥ, Kitāb al-Tafsīr", v: "24:11",
    en: ["The verse shown begins the passage on the ifk (the slander). Whose innocence does it declare?", ["ʿĀʾisha, the Mother of the Believers", "Maryam, the mother of ʿĪsā", "Zaynab bint Jaḥsh", "Ḥafṣa bint ʿUmar"], "Verses 24:11 onwards were revealed to clear ʿĀʾisha of the slander spread after the campaign against Banū al-Muṣṭaliq, as narrated by her in Ṣaḥīḥ al-Bukhārī. The verse adds that the matter was not evil for the believers but good."],
    de: ["Die angezeigte Āya beginnt den Abschnitt über den ifk (die Verleumdung). Wessen Unschuld erklärt er?", ["Die ʿĀʾišas, der Mutter der Gläubigen", "Die Maryams, der Mutter ʿĪsās", "Die Zainab bint Ǧaḥšs", "Die Ḥafṣa bint ʿUmars"], "Die Āyāt ab 24:11 wurden offenbart, um ʿĀʾiša von der Verleumdung nach dem Feldzug gegen die Banū al-Muṣṭaliq freizusprechen, wie sie selbst in Ṣaḥīḥ al-Buḫārī berichtet. Die Āya fügt hinzu, dass die Sache für die Gläubigen nicht schlecht, sondern gut war."],
    ar: ["تبدأ الآية المعروضة آيات الإفك، فبراءة مَن تعلن؟", ["عائشة أم المؤمنين", "مريم أم عيسى", "زينب بنت جحش", "حفصة بنت عمر"], "نزلت هذه الآيات في براءة عائشة مما رُميت به بعد غزوة بني المصطلق، كما روت ذلك في صحيح البخاري، وأخبرت الآية أن ما وقع لم يكن شرًا للمؤمنين بل خيرًا."] },

  { id: "tfs-035", s: "tafsir", g: 2, d: 2, t: ["al-furqan", "ibad-al-rahman"], src: "Ibn Kathīr, Tafsīr, on 25:63", v: "25:63",
    en: ["How do the servants of the Most Merciful respond when the ignorant address them, according to the verse shown?", ["With words of peace, without answering in kind", "By cutting off all contact with them", "By calling on Allah to punish them", "By debating them until they give in"], "The first quality of ʿibād al-Raḥmān is humble walking; the second is that when the foolish speak to them rudely they reply with peaceable words and do not repay ignorance with ignorance."],
    de: ["Wie antworten die Diener des Allerbarmers nach der angezeigten Āya, wenn Unwissende sie ansprechen?", ["Mit Worten des Friedens, ohne Gleiches mit Gleichem zu vergelten", "Indem sie jeden Kontakt abbrechen", "Indem sie Allah um ihre Bestrafung bitten", "Indem sie mit ihnen streiten, bis sie nachgeben"], "Die erste Eigenschaft der ʿibād ar-Raḥmān ist ein demütiger Gang, die zweite, dass sie auf grobe Worte der Törichten mit friedlichen Worten antworten und Unwissenheit nicht mit Unwissenheit vergelten."],
    ar: ["بمَ يجيب عباد الرحمن الجاهلين إذا خاطبوهم بحسب الآية المعروضة؟", ["بكلام سلام دون مقابلة السفه بمثله", "بقطع كل صلة بهم", "بالدعاء عليهم بالعقوبة", "بمجادلتهم حتى يُذعنوا"], "أول صفات عباد الرحمن المشي بتواضع، والثانية أنهم إذا خاطبهم السفهاء بسوء ردّوا بقول سليم ولم يقابلوا الجهل بالجهل."] },

  { id: "tfs-036", s: "tafsir", g: 2, d: 2, t: ["al-furqan", "ibad-al-rahman", "spending"], src: "Ibn Kathīr, Tafsīr, on 25:67", v: "25:67",
    en: ["What does the verse shown teach about how the servants of the Most Merciful spend?", ["Neither wasteful nor stingy, but balanced between the two", "Giving away all they own and keeping nothing back", "Spending only on their own families and relatives", "Saving their wealth so as to leave it to their heirs"], "The verse praises moderation: they neither squander nor hold back, but spend in a just middle way; Ibn Kathīr links it to other verses forbidding both extremes."],
    de: ["Was lehrt die angezeigte Āya darüber, wie die Diener des Allerbarmers ausgeben?", ["Weder verschwenderisch noch geizig, sondern ausgewogen", "Sie geben alles weg und behalten nichts zurück", "Sie geben nur für die eigene Familie und Verwandte aus", "Sie sparen ihr Vermögen, um es den Erben zu hinterlassen"], "Die Āya lobt das rechte Maß: Sie verschwenden nicht und halten nicht zurück, sondern geben in gerechter Mitte; Ibn Kaṯīr verbindet sie mit anderen Āyāt, die beide Extreme verbieten."],
    ar: ["ماذا تعلّم الآية المعروضة عن إنفاق عباد الرحمن؟", ["لا يسرفون ولا يبخلون بل يعتدلون", "يتصدقون بكل ما يملكون", "لا ينفقون إلا على أهليهم", "يدّخرون أموالهم كلها للكبر"], "تمدح الآية الاعتدال، فلا تبذير ولا تقتير بل وسط عدل، وربطها ابن كثير بآيات أخرى تنهى عن الطرفين."] },

  { id: "tfs-037", s: "tafsir", g: 2, d: 2, t: ["luqman", "parents"], src: "Ibn Kathīr, Tafsīr, on 31:14", v: "31:14",
    en: ["Within Luqmān's advice, the verse shown speaks of parents. What does it command?", ["Gratitude to Allah and to one's parents", "Obedience to parents even in shirk", "Leaving one's parents to seek knowledge", "Giving parents a fixed share of income"], "The verse mentions the mother's hardship in pregnancy and nursing and commands thanks to Allah and to the parents; the next verse adds that they are not to be obeyed if they call to shirk, though they are still treated kindly."],
    de: ["Innerhalb der Ratschläge Luqmāns spricht die angezeigte Āya von den Eltern. Was gebietet sie?", ["Dankbarkeit gegenüber Allah und den Eltern", "Gehorsam gegenüber den Eltern auch im Schirk", "Die Eltern zu verlassen, um Wissen zu suchen", "Den Eltern einen festen Anteil am Einkommen zu geben"], "Die Āya erwähnt die Mühe der Mutter in Schwangerschaft und Stillzeit und gebietet Dank an Allah und die Eltern; die folgende Āya ergänzt, dass man ihnen im Schirk nicht gehorcht, sie aber weiter gut behandelt."],
    ar: ["في وصايا لقمان تتحدث الآية المعروضة عن الوالدين، فبمَ تأمر؟", ["بشكر الله وشكر الوالدين", "بطاعة الوالدين ولو في الشرك", "بترك الوالدين لطلب العلم", "بإعطاء الوالدين نصيبًا ثابتًا من الدخل"], "تذكر الآية مشقة الأم في الحمل والرضاع وتأمر بشكر الله والوالدين، وتضيف الآية التالية أنهما لا يُطاعان في الشرك مع بقاء مصاحبتهما بالمعروف."] },

  { id: "tfs-038", s: "tafsir", g: 2, d: 2, t: ["luqman", "manners"], src: "Ibn Kathīr, Tafsīr, on 31:18–19", v: "31:19",
    en: ["What manners does Luqmān teach in the verse shown?", ["Moderation in walking and lowering the voice", "Walking quickly to show eagerness", "Raising the voice to be clearly heard", "Speaking only when spoken to"], "Luqmān tells his son to be moderate in his pace and to lower his voice, noting that the most unpleasant of sounds is the braying of donkeys; the verse before forbids turning one's cheek away from people in pride."],
    de: ["Welche Umgangsformen lehrt Luqmān in der angezeigten Āya?", ["Maß im Gehen und eine gedämpfte Stimme", "Schnelles Gehen, um Eifer zu zeigen", "Die Stimme zu heben, um gut gehört zu werden", "Nur zu sprechen, wenn man angesprochen wird"], "Luqmān mahnt seinen Sohn zu einem gemäßigten Gang und einer gesenkten Stimme und bemerkt, dass der hässlichste Laut das Schreien der Esel ist; die Āya davor verbietet, sich aus Hochmut von den Menschen abzuwenden."],
    ar: ["ما الآداب التي يعلّمها لقمان في الآية المعروضة؟", ["القصد في المشي وخفض الصوت", "الإسراع في المشي إظهارًا للحرص", "رفع الصوت ليُسمع جيدًا", "ألّا يتكلم إلا إذا كُلّم"], "أمر لقمان ابنه بالتوسط في مشيه وخفض صوته، وذكر أن أقبح الأصوات نهيق الحمير، ونهت الآية قبلها عن الإعراض عن الناس تكبرًا."] },

  { id: "tfs-039", s: "tafsir", g: 2, d: 3, t: ["ya-sin", "people-of-the-town"], src: "Ibn Kathīr, Tafsīr, on 36:13–14", v: "36:14",
    en: ["In the parable of the town in Sūrat Yā Sīn, how many messengers were sent, according to the verse shown?", ["Two, then they were reinforced with a third", "One, who was later joined by his brother", "Three at the same time", "Seven, one for each tribe"], "Two messengers were sent and rejected, and Allah strengthened them with a third. Many mufassirūn identified the town as Anṭākiya (Antioch), though Ibn Kathīr raises doubts about this identification."],
    de: ["Wie viele Gesandte wurden im Gleichnis der Stadt in Sūrat Yā Sīn nach der angezeigten Āya geschickt?", ["Zwei, die dann durch einen dritten verstärkt wurden", "Einer, zu dem später sein Bruder kam", "Drei gleichzeitig", "Sieben, einer für jeden Stamm"], "Zwei Gesandte wurden geschickt und abgelehnt, und Allah stärkte sie durch einen dritten. Viele Kommentatoren identifizierten die Stadt mit Anṭākiya (Antiochia), Ibn Kaṯīr äußert daran jedoch Zweifel."],
    ar: ["في مثل أصحاب القرية في سورة يس، كم رسولًا أُرسل بحسب الآية المعروضة؟", ["اثنان ثم عُزّزا بثالث", "واحد لحق به أخوه", "ثلاثة في وقت واحد", "سبعة لكل قبيلة رسول"], "أُرسل رسولان فكُذّبا فقوّاهما الله بثالث. وذكر كثير من المفسرين أن القرية أنطاكية، وأبدى ابن كثير تحفظًا على هذا التعيين."] },

  { id: "tfs-040", s: "tafsir", g: 2, d: 3, t: ["ya-sin", "people-of-the-town", "dawah"], src: "Ibn Kathīr, Tafsīr, on 36:20–27", v: "36:20",
    en: ["What did the man who came running from the far end of the city urge in the verse shown?", ["That his people follow the messengers", "That his people expel the messengers", "That the messengers leave quietly", "That the town choose a new king"], "He called his people to follow the messengers, who asked no reward and were rightly guided. He was killed, and the following verses show him wishing that his people knew of the honour he received."],
    de: ["Wozu rief der Mann, der vom äußersten Ende der Stadt herbeieilte, in der angezeigten Āya auf?", ["Dass sein Volk den Gesandten folge", "Dass sein Volk die Gesandten vertreibe", "Dass die Gesandten still abziehen", "Dass die Stadt einen neuen König wähle"], "Er rief sein Volk auf, den Gesandten zu folgen, die keinen Lohn verlangten und rechtgeleitet waren. Er wurde getötet, und die folgenden Āyāt zeigen ihn mit dem Wunsch, sein Volk wüsste von der Ehre, die er erhielt."],
    ar: ["إلامَ دعا الرجل الذي جاء مسرعًا من أطراف المدينة في الآية المعروضة؟", ["أن يتّبع قومه المرسلين", "أن يطرد قومه المرسلين", "أن يرحل المرسلون بهدوء", "أن تختار القرية ملكًا جديدًا"], "دعا قومه إلى اتباع الرسل لأنهم لا يطلبون مقابلًا وهم على هدى، فقتلوه، وتُظهره الآيات بعدها يتمنى لو علم قومه بما أكرمه الله به."] },

  { id: "tfs-041", s: "tafsir", g: 2, d: 3, t: ["al-hujurat", "verification"], src: "Ibn Kathīr, Tafsīr, on 49:6", v: "49:6",
    en: ["What principle does the verse shown establish?", ["Verifying news brought by an untrustworthy person before acting", "Rejecting every report that comes from one person", "Punishing anyone who brings bad news", "Accepting news only from relatives"], "The verse commands tabayyun: check a report from a fāsiq before acting on it, lest harm be done to people out of ignorance. Many mufassirūn mention as its occasion al-Walīd ibn ʿUqba's report about Banū al-Muṣṭaliq."],
    de: ["Welchen Grundsatz stellt die angezeigte Āya auf?", ["Nachrichten eines Unzuverlässigen vor dem Handeln zu prüfen", "Jeden Bericht einer Einzelperson abzulehnen", "Jeden zu bestrafen, der schlechte Nachrichten bringt", "Nachrichten nur von Verwandten anzunehmen"], "Die Āya gebietet tabayyun: Den Bericht eines fāsiq vor dem Handeln prüfen, damit man nicht aus Unwissenheit Menschen schadet. Viele Kommentatoren nennen als Anlass den Bericht al-Walīd ibn ʿUqbas über die Banū al-Muṣṭaliq."],
    ar: ["ما المبدأ الذي تقرّره الآية المعروضة؟", ["التثبت من خبر غير الموثوق قبل العمل به", "ردّ كل خبر ينقله شخص واحد", "معاقبة كل من يأتي بخبر سيئ", "قبول الأخبار من الأقارب فقط"], "تأمر الآية بالتبيّن في خبر الفاسق قبل العمل به لئلا يُصاب قوم بجهالة، وذكر كثير من المفسرين أن سببها خبر الوليد بن عقبة عن بني المصطلق."] },

  { id: "tfs-042", s: "tafsir", g: 2, d: 2, t: ["al-hujurat", "ethics-of-speech"], src: "Ibn Kathīr, Tafsīr, on 49:12", v: "49:12",
    en: ["To what does the verse shown liken backbiting (ghība)?", ["Eating the flesh of one's dead brother", "Drinking from a poisoned well", "Building a house on sand", "Stealing from an orphan's wealth"], "Al-Ḥujurāt forbids excessive suspicion, spying and backbiting, and portrays backbiting as eating a dead brother's flesh, something everyone finds repulsive."],
    de: ["Womit vergleicht die angezeigte Āya die üble Nachrede (ġība)?", ["Mit dem Essen des Fleisches des toten Bruders", "Mit dem Trinken aus einem vergifteten Brunnen", "Mit dem Bau eines Hauses auf Sand", "Mit dem Diebstahl am Vermögen einer Waise"], "Al-Ḥuǧurāt verbietet übermäßigen Argwohn, Ausspionieren und üble Nachrede und stellt die üble Nachrede als das Essen des Fleisches des toten Bruders dar, was jeder verabscheut."],
    ar: ["بمَ شبّهت الآية المعروضة الغيبة؟", ["بأكل لحم الأخ الميت", "بالشرب من بئر مسمومة", "ببناء بيت على الرمل", "بسرقة مال اليتيم"], "تنهى سورة الحجرات عن كثير من الظن والتجسس والغيبة، وتصوّر الغيبة بأكل لحم الأخ ميتًا، وهو أمر يكرهه كل أحد."] },

  { id: "tfs-043", s: "tafsir", g: 2, d: 2, t: ["al-hujurat", "taqwa"], src: "Ibn Kathīr, Tafsīr, on 49:13", v: "49:13",
    en: ["According to the verse shown, what makes a person most honourable before Allah?", ["Taqwā, being most God-conscious", "Noble lineage and tribe", "Wealth and number of children", "Being born in Makka"], "The verse states that people were made nations and tribes so that they may know one another, and that the most honoured before Allah is the most God-fearing, not the one of higher descent."],
    de: ["Was macht einen Menschen nach der angezeigten Āya vor Allah am angesehensten?", ["Die Taqwā, die größte Gottesfurcht", "Edle Abstammung und Stamm", "Reichtum und viele Kinder", "Die Geburt in Mekka"], "Die Āya sagt, die Menschen seien zu Völkern und Stämmen gemacht, damit sie einander kennenlernen, und der Angesehenste vor Allah sei der Gottesfürchtigste, nicht der mit der höheren Abstammung."],
    ar: ["ما الذي يجعل الإنسان أكرم عند الله بحسب الآية المعروضة؟", ["التقوى", "شرف النسب والقبيلة", "كثرة المال والولد", "المولد في مكة"], "تبيّن الآية أن الله جعل الناس أممًا وقبائل ليعرف بعضهم بعضًا، وأن أرفعهم منزلة عنده أشدّهم تقوى لا أعلاهم نسبًا."] },

  { id: "tfs-044", s: "tafsir", g: 2, d: 2, t: ["al-waqia", "three-groups"], src: "Ibn Kathīr, Tafsīr, on 56:7–14", v: "56:10",
    en: ["Sūrat al-Wāqiʿa divides people into three groups. Which group does the verse shown name?", ["The forerunners (al-sābiqūn)", "The people of the right", "The people of the left", "The people of the heights"], "Al-Wāqiʿa names the people of the right, the people of the left and the forerunners; the forerunners, those foremost in good, are the ones brought near (al-muqarrabūn). The people of the heights (al-Aʿrāf) belong to Sūrat al-Aʿrāf."],
    de: ["Sūrat al-Wāqiʿa teilt die Menschen in drei Gruppen. Welche nennt die angezeigte Āya?", ["Die Vorausgehenden (as-sābiqūn)", "Die Leute der Rechten", "Die Leute der Linken", "Die Leute der Anhöhen"], "Al-Wāqiʿa nennt die Leute der Rechten, die Leute der Linken und die Vorausgehenden; diese, die im Guten Vordersten, sind die Nahegebrachten (al-muqarrabūn). Die Leute der Anhöhen (al-Aʿrāf) gehören zur Sūrat al-Aʿrāf."],
    ar: ["تقسم سورة الواقعة الناس ثلاثة أصناف، فأيها تذكره الآية المعروضة؟", ["السابقون", "أصحاب الميمنة", "أصحاب المشأمة", "أصحاب الأعراف"], "تذكر الواقعة أصحاب الميمنة وأصحاب المشأمة والسابقين، والسابقون إلى الخيرات هم المقرّبون، أما أصحاب الأعراف ففي سورة الأعراف."] },

  { id: "tfs-045", s: "tafsir", g: 2, d: 2, t: ["al-hadid", "surah-names"], src: "Ibn Kathīr, Tafsīr, on 57:25", v: "57:25",
    en: ["Sūrat al-Ḥadīd takes its name from the verse shown. What does the verse say about iron?", ["It was sent down with great might and benefits for people", "It must never be used for weapons of any kind", "It was the material from which Nūḥ built the Ark", "It was the metal that the Golden Calf was cast from"], "The verse mentions the sending of messengers with the Book and the balance, and of iron with its great might and many benefits. The calf was made of the people's ornaments, not of iron."],
    de: ["Sūrat al-Ḥadīd hat ihren Namen von der angezeigten Āya. Was sagt die Āya über das Eisen?", ["Es wurde mit großer Kraft und Nutzen für die Menschen herabgesandt", "Es dürfe niemals für Waffen irgendeiner Art verwendet werden", "Es war der Baustoff, aus dem Nūḥ die Arche baute", "Es war das Metall, aus dem das Goldene Kalb gegossen wurde"], "Die Āya erwähnt die Sendung der Gesandten mit der Schrift und der Waage sowie das Eisen mit seiner großen Kraft und vielfachem Nutzen. Das Kalb wurde aus Schmuck gefertigt, nicht aus Eisen."],
    ar: ["سُمّيت سورة الحديد بما في الآية المعروضة، فماذا تقول الآية عن الحديد؟", ["أنه أُنزل وفيه قوة عظيمة ونفع للناس", "أنه لا يُستعمل في الحرب أبدًا", "أنه مادة سفينة نوح", "أنه معدن العجل الذهبي"], "تذكر الآية إرسال الرسل بالكتاب والميزان، وإنزال الحديد بما فيه من قوة ومنافع كثيرة، أما العجل فصُنع من الحليّ لا من الحديد."] },

  { id: "tfs-046", s: "tafsir", g: 2, d: 2, t: ["al-hashr", "divine-names"], src: "Ibn Kathīr, Tafsīr, on 59:22–24", v: "59:23",
    en: ["What characterises the closing verses of Sūrat al-Ḥashr, including the verse shown?", ["A concentrated series of Allah's beautiful names", "A list of the prophets sent to Banū Isrāʾīl", "Detailed rules of inheritance", "The description of the Day of Judgement"], "The last three verses of al-Ḥashr gather many of al-asmāʾ al-ḥusnā, such as the King, the Holy, Peace, the Guardian and the Compeller, and end by saying that everything in the heavens and earth glorifies Him."],
    de: ["Was kennzeichnet die Schlussverse der Sūrat al-Ḥašr einschließlich der angezeigten Āya?", ["Eine dichte Reihe der schönsten Namen Allahs", "Eine Liste der zu den Banū Isrāʾīl gesandten Propheten", "Ausführliche Erbschaftsregeln", "Die Beschreibung des Jüngsten Tages"], "Die letzten drei Āyāt von al-Ḥašr sammeln viele der al-asmāʾ al-ḥusnā, etwa der König, der Heilige, der Friede, der Wächter und der Bezwinger, und enden damit, dass alles in den Himmeln und auf der Erde Ihn preist."],
    ar: ["ما الذي يميّز خاتمة سورة الحشر ومنها الآية المعروضة؟", ["اجتماع عدد كبير من أسماء الله الحسنى", "تعداد الأنبياء المرسلين إلى بني إسرائيل", "تفصيل أحكام المواريث", "وصف يوم القيامة"], "جمعت الآيات الثلاث الأخيرة من سورة الحشر كثيرًا من الأسماء الحسنى كالملك والقدوس والسلام والمهيمن والجبار، وختمت بتسبيح ما في السماوات والأرض له."] },

  { id: "tfs-047", s: "tafsir", g: 2, d: 2, t: ["al-duha", "orphans"], src: "Ibn Kathīr, Tafsīr, on 93:6–11", v: "93:9",
    en: ["After reminding the Prophet that he was found an orphan and sheltered, what does Sūrat al-Ḍuḥā command in the verse shown?", ["Not to treat the orphan harshly", "To adopt every orphan in Makka", "To give orphans a share of the spoils", "To appoint guardians for orphans"], "Having recalled Allah's favours to him (orphanhood, guidance, sufficiency), the surah commands in return not to oppress the orphan, not to repel the one who asks, and to speak of his Lord's blessing."],
    de: ["Nachdem Sūrat aḍ-Ḍuḥā den Propheten daran erinnert, dass er als Waise Obdach fand, was gebietet sie in der angezeigten Āya?", ["Die Waise nicht hart zu behandeln", "Jede Waise in Mekka zu adoptieren", "Waisen einen Teil der Beute zu geben", "Vormünder für Waisen zu bestellen"], "Nach der Erinnerung an Allahs Wohltaten (Waisentum, Rechtleitung, Genügsamkeit) gebietet die Sure im Gegenzug, die Waise nicht zu unterdrücken, den Bittenden nicht abzuweisen und von der Gnade seines Herrn zu erzählen."],
    ar: ["بعد أن ذكّرت سورة الضحى النبي ﷺ بيُتمه وإيوائه، بمَ أمرت في الآية المعروضة؟", ["ألّا يُعامَل اليتيم بقسوة", "أن يتبنّى كل يتيم في مكة", "أن يُعطى الأيتام سهمًا من الغنيمة", "أن يُعيَّن للأيتام أوصياء"], "بعد تعداد نعم الله عليه من الإيواء والهداية والإغناء أمرته السورة شكرًا لها ألّا يظلم اليتيم ولا يزجر من يسأله وأن يذكر نعمة ربه ويظهرها."] },

  { id: "tfs-048", s: "tafsir", g: 2, d: 2, t: ["al-takwir", "day-of-judgement", "justice"], src: "Ibn Kathīr, Tafsīr, on 81:8–9", v: "81:8",
    en: ["Among the scenes of the Last Day in Sūrat al-Takwīr, what does the verse shown and the one after it describe?", ["The girl buried alive is asked for what sin she was killed", "The scrolls of deeds are spread open before all creation", "The angels descend in rows around the gathered people", "The scales of deeds are set up for the reckoning"], "The verse refers to the pre-Islamic practice of burying daughters alive (waʾd). Asking the victim rather than the killer is a severe rebuke of those who did it."],
    de: ["Was beschreiben die angezeigte Āya und die folgende unter den Szenen des Jüngsten Tages in Sūrat at-Takwīr?", ["Das lebendig begrabene Mädchen wird nach seiner Schuld gefragt", "Die Schriften der Taten werden vor allen aufgeschlagen", "Die Engel steigen in Reihen um die Versammelten herab", "Die Waagen der Taten werden zur Abrechnung aufgestellt"], "Die Āya bezieht sich auf die vorislamische Sitte, Töchter lebendig zu begraben (waʾd). Dass das Opfer und nicht der Täter gefragt wird, ist ein schwerer Tadel der Täter."],
    ar: ["من مشاهد يوم القيامة في سورة التكوير، ماذا تصف الآية المعروضة والتي بعدها؟", ["سؤال البنت المدفونة حية عن ذنب قتلها", "نشر صحف الأعمال أمام الخلائق كلها", "نزول الملائكة صفوفًا حول الناس", "نصب موازين الأعمال للحساب"], "تشير الآية إلى عادة الجاهلية في وأد البنات، وفي توجيه السؤال إلى البنت المقتولة دون القاتل توبيخ شديد لمن فعل ذلك."] },
  // ---------- stage 3 ----------
  { id: "tfs-049", s: "tafsir", g: 3, d: 3, t: ["al-kahf", "musa-and-khidr", "hadith-in-tafsir"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb al-ʿIlm and Kitāb al-Tafsīr (hadith of Ubayy ibn Kaʿb)", v: "18:60",
    en: ["According to the hadith of Ubayy ibn Kaʿb in Ṣaḥīḥ al-Bukhārī, why did Mūsā set out for the junction of the two seas mentioned in the verse shown?", ["He had called himself the most learned, and was told of one more learned", "He was fleeing from Firʿawn after the killing of the Egyptian man", "He was searching for the tablets of the Torah that were lost at sea", "He had been sent to call a people living on the shore to tawḥīd"], "In the hadith, Mūsā was asked who was most knowledgeable and answered 'I', without attributing knowledge to Allah; Allah informed him of a servant at the junction of the two seas who knew more, and Mūsā set out to learn from him."],
    de: ["Warum brach Mūsā nach dem Hadith von Ubayy ibn Kaʿb in Ṣaḥīḥ al-Buḫārī zum Zusammenfluss der zwei Meere in der angezeigten Āya auf?", ["Er hatte sich den Wissendsten genannt und erfuhr von einem Gelehrteren", "Er floh nach der Tötung des Ägypters vor Firʿawn und seinen Leuten", "Er suchte die Tafeln der Tora, die im Meer verloren gegangen waren", "Er war gesandt, ein Volk an der Küste zum Tauḥīd zu rufen"], "Im Hadith wurde Mūsā gefragt, wer der Wissendste sei, und antwortete „ich“, ohne das Wissen Allah zuzuschreiben; Allah teilte ihm mit, dass ein Diener am Zusammenfluss der zwei Meere mehr wisse, und Mūsā brach auf, um von ihm zu lernen."],
    ar: ["لماذا خرج موسى إلى مجمع البحرين المذكور في الآية المعروضة بحسب حديث أبي بن كعب في صحيح البخاري؟", ["لأنه قال إنه أعلم الناس فأخبره الله بعبد أعلم منه", "لأنه كان فارًّا من فرعون بعد قتل المصري", "لأنه كان يبحث عن الألواح الضائعة في البحر", "لأنه أُرسل إلى قوم يسكنون على البحر"], "في الحديث سُئل موسى عن أعلم الناس فأجاب بأنه هو، ولم ينسب العلم إلى الله، فأخبره الله أن له عبدًا بمجمع البحرين هو أعلم منه، فخرج موسى ليتعلّم منه."] },

  { id: "tfs-050", s: "tafsir", g: 3, d: 3, t: ["al-kahf", "companionship"], src: "Ibn Kathīr, Tafsīr, on 18:28", v: "18:28",
    en: ["What is the Prophet commanded in the verse shown?", ["To stay patiently with those who call on their Lord morning and evening", "To leave Makka and live in seclusion like the people of the cave", "To pray through the night until his feet became swollen", "To give the leaders of Quraysh precedence over the poor believers"], "The verse commands patience in the company of sincere worshippers, even if poor, and forbids turning one's eyes from them out of desire for worldly adornment. The mufassirūn mention that Quraysh nobles had asked for the poor believers to be sent away."],
    de: ["Was wird dem Propheten in der angezeigten Āya geboten?", ["Geduldig bei denen zu bleiben, die ihren Herrn morgens und abends anrufen", "Mekka zu verlassen und wie die Leute der Höhle zurückgezogen zu leben", "Die ganze Nacht zu beten, bis seine Füße anschwellen", "Den Führern der Quraisch Vorrang vor den armen Gläubigen zu geben"], "Die Āya gebietet Geduld in der Gesellschaft aufrichtiger Anbeter, auch wenn sie arm sind, und verbietet, sich aus Verlangen nach weltlichem Schmuck von ihnen abzuwenden. Die Kommentatoren erwähnen, dass Adlige der Quraisch verlangt hatten, die armen Gläubigen fortzuschicken."],
    ar: ["بمَ أُمر النبي ﷺ في الآية المعروضة؟", ["أن يلازم صابرًا من يدعون ربهم صباحًا ومساءً", "أن يترك مكة ويقيم عند أهل الكهف", "أن يقوم الليل حتى تتورم قدماه", "أن يُعرض عن الفقراء ليكسب الكبراء"], "تأمر الآية بملازمة العابدين المخلصين ولو كانوا فقراء، وتنهى عن صرف النظر عنهم طلبًا لزينة الدنيا، وذكر المفسرون أن كبراء قريش طلبوا إبعاد ضعفاء المؤمنين."] },

  { id: "tfs-051", s: "tafsir", g: 3, d: 3, t: ["al-kahf", "sincerity", "accepted-deeds"], src: "Ibn Kathīr, Tafsīr, on 18:110", v: "18:110",
    en: ["Ibn Kathīr says the end of the verse shown contains the two pillars of an accepted deed. What are they?", ["Sincerity to Allah and following the Sunna", "Knowledge before action and patience after it", "Intention at the start and supplication at the end", "Ritual purity and facing the qibla"], "The verse asks whoever hopes to meet his Lord to do righteous work and associate no one in worship. Ibn Kathīr explains: the deed must be correct according to the Sharīʿa and done sincerely for Allah alone."],
    de: ["Ibn Kaṯīr sagt, das Ende der angezeigten Āya enthalte die zwei Säulen einer angenommenen Tat. Welche sind es?", ["Aufrichtigkeit gegenüber Allah und Befolgung der Sunna", "Wissen vor dem Handeln und Geduld danach", "Absicht am Anfang und Bittgebet am Ende", "Rituelle Reinheit und Ausrichtung zur Qibla"], "Die Āya fordert jeden, der auf die Begegnung mit seinem Herrn hofft, zu rechtschaffenem Werk auf und dazu, niemanden in der Anbetung beizugesellen. Ibn Kaṯīr erklärt: Die Tat muss der Scharia entsprechen und allein für Allah aufrichtig verrichtet werden."],
    ar: ["قال ابن كثير إن آخر الآية المعروضة جمع ركني العمل المتقبَّل، فما هما؟", ["الإخلاص لله والموافقة لهدي النبي ﷺ", "العلم قبل العمل والصبر بعده", "النية في أوله والدعاء في آخره", "الطهارة واستقبال القبلة"], "تأمر الآية من يرجو لقاء ربه بالعمل الصالح وترك الإشراك في العبادة، وبيّن ابن كثير أن العمل لا يُقبل حتى يكون موافقًا للشريعة خالصًا لله وحده."] },

  { id: "tfs-052", s: "tafsir", g: 3, d: 3, t: ["ta-ha", "seeking-knowledge"], src: "Ibn Kathīr, Tafsīr, on 20:114", v: "20:114",
    en: ["Besides the prayer for increase in knowledge, what instruction does the verse shown give the Prophet?", ["Not to hasten with the Quran before its revelation is complete", "Not to teach the Quran to anyone until Ramaḍān had come", "To have each verse written down before memorising it", "To recite the Quran aloud only in the prayer at night"], "The Prophet used to hurry to repeat the revelation while it was being delivered; he was told not to hasten and to ask instead for more knowledge. Scholars note this is the only thing he was commanded to ask an increase of."],
    de: ["Welche Anweisung gibt die angezeigte Āya dem Propheten neben dem Bittgebet um mehr Wissen?", ["Nicht mit dem Koran zu eilen, bevor seine Offenbarung vollendet ist", "Niemanden den Koran zu lehren, bevor der Ramaḍān gekommen ist", "Jede Āya aufschreiben zu lassen, bevor er sie auswendig lernt", "Den Koran nur im Nachtgebet laut zu rezitieren"], "Der Prophet wiederholte die Offenbarung eilig, während sie übermittelt wurde; ihm wurde gesagt, nicht zu eilen und stattdessen um mehr Wissen zu bitten. Die Gelehrten bemerken, dass dies das Einzige ist, um dessen Vermehrung er zu bitten angewiesen wurde."],
    ar: ["إلى جانب الدعاء بزيادة العلم، ما التوجيه الذي تحمله الآية المعروضة للنبي ﷺ؟", ["ألّا يتعجّل بالقرآن قبل أن يتمّ إليه وحيه", "ألّا يعلّم القرآن أحدًا قبل رمضان", "أن يكتب كل آية قبل حفظها", "ألّا يقرأ القرآن إلا في قيام الليل"], "كان النبي ﷺ يسابق جبريل في ترديد الوحي، فنُهي عن العجلة وأُمر بسؤال الزيادة من العلم، ونبّه العلماء إلى أنه لم يُؤمر بطلب الزيادة من شيء إلا من العلم."] },

  { id: "tfs-053", s: "tafsir", g: 3, d: 3, t: ["ta-ha", "adam"], src: "Ibn Kathīr, Tafsīr, on 20:115–122", v: "20:120",
    en: ["In the version of Ādam's story in Ṭā Hā, how did Shayṭān present the forbidden tree in the verse shown?", ["As the tree of immortality and a kingdom that never decays", "As the tree of knowledge of good and evil", "As a tree whose fruit gives the sight of angels", "As a tree that would make him a prophet"], "Shayṭān whispered to Ādam, offering to guide him to 'the tree of eternity' and a never-ending dominion. The 'knowledge of good and evil' wording comes from the Biblical account, not the Quran."],
    de: ["Wie stellte Šaiṭān in der Fassung der Ādam-Geschichte in Ṭā Hā den verbotenen Baum in der angezeigten Āya dar?", ["Als Baum der Unsterblichkeit und eines unvergänglichen Königreichs", "Als Baum der Erkenntnis von Gut und Böse", "Als Baum, dessen Frucht die Sicht der Engel verleiht", "Als Baum, der ihn zum Propheten machen würde"], "Šaiṭān flüsterte Ādam zu und bot an, ihn zum „Baum der Ewigkeit“ und zu einer nie vergehenden Herrschaft zu führen. Die Formulierung „Erkenntnis von Gut und Böse“ stammt aus der biblischen Erzählung, nicht aus dem Koran."],
    ar: ["في قصة آدم في سورة طه، كيف صوّر الشيطان الشجرة المحرّمة في الآية المعروضة؟", ["بأنها شجرة الخلود وطريق ملك لا يفنى", "بأنها شجرة معرفة الخير والشر", "بأن ثمرها يمنح رؤية الملائكة", "بأنها تجعله نبيًا"], "وسوس الشيطان لآدم وعرض أن يدلّه على شجرة يخلد بها وملك لا يزول، أما وصف معرفة الخير والشر فهو من رواية أهل الكتاب لا من القرآن."] },

  { id: "tfs-054", s: "tafsir", g: 3, d: 4, t: ["al-nur", "light-verse"], src: "Ibn Kathīr, Tafsīr, on 24:35; al-Ṭabarī, Jāmiʿ al-Bayān, on 24:35", v: "24:35",
    en: ["How did Ubayy ibn Kaʿb, as reported by al-Ṭabarī and Ibn Kathīr, interpret 'the parable of His light' in the verse shown?", ["The light of faith and the Quran in the believer's heart", "The light of the sun and the moon in the sky above", "The light that will shine for believers on the Ṣirāṭ", "The light that shone from the Kaʿba over all of Makka"], "Ubayy explained the parable as the light Allah places in the heart of the believer: the chest is the niche, the heart the glass, faith and the Quran the lamp. Ibn ʿAbbās interpreted the opening of the verse as Allah being the guide of those in the heavens and the earth."],
    de: ["Wie deutete Ubayy ibn Kaʿb nach den Berichten bei aṭ-Ṭabarī und Ibn Kaṯīr „das Gleichnis Seines Lichtes“ in der angezeigten Āya?", ["Das Licht von Glauben und Koran im Herzen des Gläubigen", "Das Licht von Sonne und Mond am Himmel über uns", "Das Licht, das den Gläubigen auf dem Ṣirāṭ leuchten wird", "Das Licht, das von der Kaaba über ganz Mekka strahlte"], "Ubayy erklärte das Gleichnis als das Licht, das Allah ins Herz des Gläubigen legt: die Brust ist die Nische, das Herz das Glas, Glaube und Koran die Lampe. Ibn ʿAbbās deutete den Anfang der Āya so, dass Allah der Rechtleiter der Bewohner der Himmel und der Erde ist."],
    ar: ["كيف فسّر أبي بن كعب، فيما رواه الطبري وابن كثير، مثل نوره في الآية المعروضة؟", ["بنور الإيمان والقرآن في قلب المؤمن", "بنور الشمس والقمر في السماء", "بالنور الذي يضيء على الصراط", "بنور الكعبة على مكة"], "فسّر أبي المثل بالنور الذي يجعله الله في قلب المؤمن: صدره الكوّة، وقلبه الزجاج، والإيمان والقرآن السراج. وفسّر ابن عباس أول الآية بأن الله هادي أهل السماوات والأرض."] },

  { id: "tfs-055", s: "tafsir", g: 3, d: 4, t: ["al-nur", "light-verse"], src: "Ibn Kathīr, Tafsīr, on 24:35", v: "24:35",
    en: ["The olive tree in the verse shown is described as 'neither of the east nor of the west'. What is the explanation reported from Ibn ʿAbbās?", ["It stands in the open, sunlit all day, so its oil is purest", "It grows only in Shām, which lies between east and west", "It is a tree of Paradise that is not found on earth", "It belongs to no nation, so no one may claim to own it"], "Ibn Kathīr reports from Ibn ʿAbbās and others that the tree is not shaded at sunrise or sunset but exposed to the sun from morning to evening, which makes its oil the clearest and finest."],
    de: ["Der Ölbaum in der angezeigten Āya wird als „weder östlich noch westlich“ beschrieben. Welche Erklärung wird von Ibn ʿAbbās überliefert?", ["Er steht frei und den ganzen Tag in der Sonne, daher ist sein Öl am reinsten", "Er wächst nur in Šām, das zwischen Osten und Westen liegt", "Er ist ein Baum des Paradieses, den es auf Erden nicht gibt", "Er gehört keinem Volk, sodass niemand ihn besitzen darf"], "Ibn Kaṯīr überliefert von Ibn ʿAbbās und anderen, dass der Baum weder bei Sonnenaufgang noch bei Sonnenuntergang beschattet ist, sondern von morgens bis abends in der Sonne steht, was sein Öl am klarsten und edelsten macht."],
    ar: ["وُصفت شجرة الزيتون في الآية المعروضة بأنها لا شرقية ولا غربية، فما التفسير المروي عن ابن عباس؟", ["أنها في أرض مكشوفة تصيبها الشمس طوال النهار فيصفو زيتها", "أنها لا تنبت إلا في الشام بين المشرق والمغرب", "أنها من شجر الجنة لا توجد في الأرض", "أنها لا تنتسب إلى أمة فلا يملكها أحد"], "روى ابن كثير عن ابن عباس وغيره أن الشجرة لا يحجبها شيء عند الشروق ولا الغروب، بل تصيبها الشمس من أول النهار إلى آخره، فيكون زيتها أصفى ما يكون."] },

  { id: "tfs-056", s: "tafsir", g: 3, d: 3, t: ["al-furqan", "ibad-al-rahman", "repentance"], src: "Ibn Kathīr, Tafsīr, on 25:68–71", v: "25:70",
    en: ["After the grave sins listed before it, what does the verse shown promise those who repent, believe and do good?", ["Allah replaces their evil deeds with good deeds", "Their punishment is merely halved", "They are forgiven but lose their rank in Paradise", "They must first repay every wrong in this world"], "The verse makes an exception from the threatened punishment for those who repent, believe and act righteously, and says Allah turns their bad deeds into good ones; the mufassirūn explain this both as a change of character and as a change in the record."],
    de: ["Was verspricht die angezeigte Āya nach den zuvor genannten schweren Sünden denen, die bereuen, glauben und Gutes tun?", ["Allah ersetzt ihre bösen Taten durch gute", "Ihre Strafe wird nur halbiert", "Ihnen wird vergeben, aber sie verlieren ihren Rang im Paradies", "Sie müssen zuerst jedes Unrecht im Diesseits begleichen"], "Die Āya nimmt diejenigen, die bereuen, glauben und rechtschaffen handeln, von der angedrohten Strafe aus und sagt, Allah verwandle ihre schlechten Taten in gute; die Kommentatoren erklären das sowohl als Wandel des Charakters als auch als Änderung im Register."],
    ar: ["بعد الكبائر المذكورة قبلها، ماذا تعد الآية المعروضة من تاب وآمن وعمل صالحًا؟", ["أن يحوّل الله سيئاتهم إلى حسنات", "أن يُخفَّف عذابهم إلى النصف فقط", "أن يُغفر لهم مع نقص منزلتهم في الجنة", "أن يؤدوا كل مظلمة في الدنيا أولًا"], "تستثني الآية التائب المؤمن العامل للصالحات من الوعيد، وتخبر أن الله يحوّل سيئاته حسنات، وفسّره المفسرون بتبدّل الأعمال والأخلاق وبتبديل ما في الصحائف."] },

  { id: "tfs-057", s: "tafsir", g: 3, d: 3, t: ["al-furqan", "ibad-al-rahman", "dua"], src: "Ibn Kathīr, Tafsīr, on 25:74", v: "25:74",
    en: ["In the verse shown, what do the servants of the Most Merciful ask for themselves at the end of their prayer?", ["To be made examples for the God-conscious", "To be granted long lives and much wealth", "To be made rulers over the unbelievers", "To be spared every hardship in this world"], "They ask for spouses and offspring who are a comfort to the eyes and to be made an imām for the muttaqūn, that is, examples in good whom others follow. The mufassirūn note this is a request for leadership in religion, not in worldly power."],
    de: ["Worum bitten die Diener des Allerbarmers in der angezeigten Āya am Ende ihres Bittgebets für sich selbst?", ["Zu Vorbildern für die Gottesfürchtigen gemacht zu werden", "Um ein langes Leben und viel Reichtum", "Zu Herrschern über die Ungläubigen gemacht zu werden", "Von jeder Mühsal im Diesseits verschont zu bleiben"], "Sie bitten um Ehepartner und Nachkommen, die ein Augentrost sind, und darum, ein imām für die Gottesfürchtigen zu werden, also Vorbilder im Guten. Die Kommentatoren betonen, dass es um Führung in der Religion geht, nicht um weltliche Macht."],
    ar: ["في الآية المعروضة، بمَ يدعو عباد الرحمن لأنفسهم في آخر دعائهم؟", ["أن يجعلهم الله قدوة للمتقين", "أن يرزقهم طول العمر وكثرة المال", "أن يجعلهم حكامًا على الكافرين", "أن يعافيهم من كل مشقة في الدنيا"], "يسألون أزواجًا وذرية يُسرّون بهم، وأن يكونوا قدوة لأهل التقوى في الخير، ونبّه المفسرون إلى أنها إمامة في الدين لا سلطان دنيوي."] },

  { id: "tfs-058", s: "tafsir", g: 3, d: 3, t: ["luqman", "divine-knowledge"], src: "Ibn Kathīr, Tafsīr, on 31:16", v: "31:16",
    en: ["What lesson does Luqmān teach with the image of a mustard seed in the verse shown?", ["Nothing is hidden from Allah; He will bring every deed forth", "A small seed of faith grows into a great and shady tree", "Charity should always begin with the smallest of gifts", "Even hard rocks can be split by patient, steady effort"], "Even if a deed were the weight of a mustard seed hidden in a rock, in the heavens or the earth, Allah would bring it forth on the Day of Judgement, for He is Subtle and All-Aware. The 'growing seed' image is from the New Testament, not this verse."],
    de: ["Welche Lehre gibt Luqmān mit dem Bild des Senfkorns in der angezeigten Āya?", ["Nichts ist Allah verborgen; Er bringt jede Tat hervor", "Ein kleiner Glaubenssamen wächst zu einem großen Baum", "Spenden sollen stets mit der kleinsten Gabe beginnen", "Selbst harte Felsen spaltet geduldige, stetige Mühe"], "Selbst wenn eine Tat das Gewicht eines Senfkorns hätte und in einem Felsen, in den Himmeln oder in der Erde verborgen wäre, brächte Allah sie am Tag des Gerichts hervor, denn Er ist feinfühlig und allkundig. Das Bild vom wachsenden Samen stammt aus dem Neuen Testament, nicht aus dieser Āya."],
    ar: ["ما العبرة التي يعلّمها لقمان بصورة حبة الخردل في الآية المعروضة؟", ["أن العمل لا يخفى على الله وسيأتي به للجزاء", "أن الإيمان الصغير ينمو شجرة عظيمة", "أن الصدقة تبدأ بأصغر عطية", "أن الصخر الصلب ينشق بالصبر"], "لو كان العمل بوزن حبة خردل مخبوءًا في صخرة أو في السماوات أو الأرض لأحضره الله يوم القيامة، فهو اللطيف الخبير. أما صورة البذرة النامية فمن الإنجيل لا من هذه الآية."] },

  { id: "tfs-059", s: "tafsir", g: 3, d: 3, t: ["luqman", "enjoining-good"], src: "Ibn Kathīr, Tafsīr, on 31:17", v: "31:17",
    en: ["Why does Luqmān pair the command to enjoin good and forbid evil with patience in the verse shown?", ["Because whoever calls to good will meet harm and must bear it", "Because patience replaces the need to speak out", "Because forbidding evil is only for rulers", "Because patience is needed only in illness"], "Luqmān commands prayer, enjoining good and forbidding evil, then patience over what befalls him; Ibn Kathīr explains that one who commands and forbids will inevitably be harmed by people, so he is told to be patient."],
    de: ["Warum verbindet Luqmān in der angezeigten Āya das Gebieten des Guten und Verbieten des Bösen mit Geduld?", ["Weil wer zum Guten ruft, Leid erfährt und es ertragen muss", "Weil Geduld das Reden überflüssig macht", "Weil das Verbieten des Bösen nur den Herrschern zusteht", "Weil Geduld nur in Krankheit nötig ist"], "Luqmān gebietet das Gebet, das Gebieten des Guten und das Verbieten des Bösen und danach Geduld bei dem, was einen trifft; Ibn Kaṯīr erklärt, wer gebietet und verbietet, werde unweigerlich von Menschen angefeindet und solle daher geduldig sein."],
    ar: ["لماذا قرن لقمان الأمر بالمعروف والنهي عن المنكر بالصبر في الآية المعروضة؟", ["لأن الداعي إلى الخير يناله أذى فعليه أن يصبر", "لأن الصبر يغني عن الكلام", "لأن النهي عن المنكر للحكام وحدهم", "لأن الصبر لا يُحتاج إليه إلا في المرض"], "أمر لقمان بإقامة الصلاة والأمر بالمعروف والنهي عن المنكر ثم بالصبر على ما يصيبه، وبيّن ابن كثير أن الآمر الناهي لا بد أن يناله من الناس أذى فأُمر بالصبر."] },

  { id: "tfs-060", s: "tafsir", g: 3, d: 4, t: ["ya-sin", "signs-in-creation", "quranic-vocabulary"], src: "Ibn Kathīr, Tafsīr, on 36:39", v: "36:39",
    en: ["In the verse shown, the moon returns at the end of its phases like the ʿurjūn. What is the ʿurjūn according to the mufassirūn?", ["The old, dried, curved stalk of a date cluster", "A crescent-shaped lamp made of bronze", "The curved stone rim of a desert well", "A hunting bow bent ready for the shot"], "Ibn ʿAbbās and others explain al-ʿurjūn al-qadīm as the stalk of a date bunch that has dried, shrivelled and curved; the waning moon becomes thin, yellowish and bent like it."],
    de: ["In der angezeigten Āya kehrt der Mond am Ende seiner Phasen wie der ʿurǧūn zurück. Was ist der ʿurǧūn nach den Kommentatoren?", ["Der alte, vertrocknete, gekrümmte Stiel einer Dattelrispe", "Eine sichelförmige Lampe aus Bronze", "Der gebogene Steinrand eines Wüstenbrunnens", "Ein zum Schuss gespannter Jagdbogen"], "Ibn ʿAbbās und andere erklären al-ʿurǧūn al-qadīm als den Stiel einer Dattelrispe, der vertrocknet, geschrumpft und gekrümmt ist; der abnehmende Mond wird dünn, gelblich und gebogen wie er."],
    ar: ["في الآية المعروضة يعود القمر في آخر منازله كالعرجون، فما العرجون عند المفسرين؟", ["عود عذق النخل إذا يبس وانحنى", "مصباح نحاسي على هيئة الهلال", "حافة بئر في الصحراء", "قوس مشدود من أقواس الصيادين"], "فسّر ابن عباس وغيره العرجون القديم بأصل العذق إذا جفّ وتقوّس، فيصير القمر في آخر الشهر دقيقًا مصفرًّا منحنيًا مثله."] },

  { id: "tfs-061", s: "tafsir", g: 3, d: 3, t: ["ya-sin", "day-of-judgement", "accountability"], src: "Ibn Kathīr, Tafsīr, on 36:65", v: "36:65",
    en: ["What happens on the Day of Judgement according to the verse shown?", ["Mouths are sealed, and hands speak and feet bear witness", "The angels read every deed aloud to all creation", "The earth swallows those who denied the Hour", "The disbelievers are given a second chance to repent"], "When the deniers reject the testimony against them, Allah seals their mouths and their own limbs testify to what they earned; similar scenes are in 24:24 and 41:20–21."],
    de: ["Was geschieht am Tag des Gerichts nach der angezeigten Āya?", ["Die Münder werden versiegelt, die Hände sprechen und die Füße bezeugen", "Die Engel lesen jede Tat vor der ganzen Schöpfung vor", "Die Erde verschlingt die Leugner der Stunde", "Die Ungläubigen erhalten eine zweite Gelegenheit zur Reue"], "Wenn die Leugner das Zeugnis gegen sich zurückweisen, versiegelt Allah ihre Münder, und ihre eigenen Glieder bezeugen, was sie erworben haben; ähnliche Szenen stehen in 24:24 und 41:20–21."],
    ar: ["ماذا يحدث يوم القيامة بحسب الآية المعروضة؟", ["تُختم الأفواه وتتكلم الأيدي وتشهد الأرجل", "تقرأ الملائكة كل عمل على رؤوس الخلائق", "تبتلع الأرض المكذبين بالساعة", "يُمنح الكافرون فرصة ثانية للتوبة"], "حين ينكر المكذبون ما يُشهد به عليهم يختم الله على أفواههم وتشهد عليهم جوارحهم بما كسبوا، ومثل ذلك في سورتي النور وفصلت."] },

  { id: "tfs-062", s: "tafsir", g: 3, d: 3, t: ["al-hujurat", "reconciliation"], src: "Ibn Kathīr, Tafsīr, on 49:9–10", v: "49:9",
    en: ["When two groups of believers fight, what does the verse shown command?", ["Make peace, and fight the aggressor until it returns to Allah's command", "Stay neutral and leave them to settle the matter themselves", "Fight both groups until each of them lays down its arms", "Support the larger group so the fighting ends quickly"], "The verse orders peace-making first; if one party continues in aggression, it is fought until it returns to Allah's command, then peace is made with justice. Ibn Kathīr notes that the fighters are still called believers, so the sin does not take them out of faith."],
    de: ["Was gebietet die angezeigte Āya, wenn zwei Gruppen von Gläubigen kämpfen?", ["Versöhnen und die übergreifende Gruppe bekämpfen, bis sie zu Allahs Gebot zurückkehrt", "Neutral bleiben und sie die Sache selbst regeln lassen, ohne einzugreifen", "Beide Gruppen bekämpfen, bis jede von ihnen die Waffen niederlegt", "Die größere Gruppe unterstützen, damit der Kampf schnell endet"], "Die Āya gebietet zuerst Versöhnung; setzt eine Partei ihre Aggression fort, wird sie bekämpft, bis sie zu Allahs Gebot zurückkehrt, dann wird gerecht Frieden gestiftet. Ibn Kaṯīr bemerkt, dass die Kämpfenden weiterhin Gläubige genannt werden, die Sünde sie also nicht aus dem Glauben bringt."],
    ar: ["إذا اقتتلت طائفتان من المؤمنين، فبمَ تأمر الآية المعروضة؟", ["الإصلاح بينهما وقتال الباغية حتى ترجع إلى أمر الله", "الحياد وتركهما يحلّان الأمر بأنفسهما", "قتال الطائفتين حتى تضع كل منهما السلاح", "نصرة الطائفة الأكثر لينتهي القتال سريعًا"], "تأمر الآية بالصلح أولًا، فإن استمرت إحداهما في العدوان قوتلت حتى تعود إلى أمر الله ثم يُصلح بينهما بالعدل. ونبّه ابن كثير إلى أن الآية سمّت المتقاتلين مؤمنين، فالمعصية لا تخرجهم من الإيمان."] },

  { id: "tfs-063", s: "tafsir", g: 3, d: 4, t: ["al-hujurat", "iman-and-islam"], src: "Ibn Kathīr, Tafsīr, on 49:14", v: "49:14",
    en: ["Which distinction does the verse shown draw when the Bedouins claim 'we believe'?", ["Outward submission (islām) versus faith settled in the heart (īmān)", "The emigrants of Makka versus the helpers of Madīna", "Obligatory prayers versus prayers that are only recommended", "The hypocrites versus the People of the Book in Madīna"], "They are told to say 'we have submitted', since faith had not yet entered their hearts. Ibn Kathīr uses the verse to show that īmān is a more specific rank than islām, while noting these Bedouins were not hypocrites."],
    de: ["Welche Unterscheidung trifft die angezeigte Āya, als die Beduinen sagen „wir glauben“?", ["Äußere Ergebung (islām) und im Herzen gefestigter Glaube (īmān)", "Die Auswanderer aus Mekka und die Helfer in Medina", "Pflichtgebete und lediglich empfohlene Gebete", "Die Heuchler und die Leute der Schrift in Medina"], "Ihnen wird gesagt, sie sollen sagen „wir haben uns ergeben“, da der Glaube noch nicht in ihre Herzen eingedrungen war. Ibn Kaṯīr zeigt damit, dass īmān eine besondere, höhere Stufe als islām ist, und betont, dass diese Beduinen keine Heuchler waren."],
    ar: ["ما الفرق الذي تقرره الآية المعروضة حين قال الأعراب آمنّا؟", ["الإسلام الظاهر والإيمان المستقر في القلب", "المهاجرون من مكة والأنصار في المدينة", "الصلاة المفروضة والصلاة المستحبة فقط", "المنافقون وأهل الكتاب في المدينة"], "أُمروا أن يصفوا أنفسهم بالإسلام لأن الإيمان لم يتمكن من قلوبهم بعد، واستدل ابن كثير بالآية على أن الإيمان أخصّ من الإسلام، مع تنبيهه على أن هؤلاء الأعراب لم يكونوا منافقين."] },

  { id: "tfs-064", s: "tafsir", g: 3, d: 3, t: ["al-rahman", "signs-in-creation"], src: "Ibn Kathīr, Tafsīr, on 55:19–22", v: "55:20",
    en: ["In the passage of the verse shown, two seas meet. What is between them?", ["A barrier (barzakh) that neither of them oversteps", "A bridge on which the believers will cross over", "A range of mountains dividing two lands", "A river of fire that appears on the Last Day"], "Allah lets two bodies of water meet, yet a barrier keeps each from overrunning the other; the passage counts this among His favours, followed by pearls and coral brought out from them."],
    de: ["Im Abschnitt der angezeigten Āya treffen zwei Meere aufeinander. Was liegt zwischen ihnen?", ["Eine Schranke (barzaḫ), die keines überschreitet", "Eine Brücke, über die die Gläubigen gehen werden", "Eine Bergkette, die zwei Länder trennt", "Ein Feuerstrom, der am Jüngsten Tag erscheint"], "Allah lässt zwei Gewässer aufeinandertreffen, doch eine Schranke hindert jedes daran, das andere zu überfluten; der Abschnitt zählt dies zu Seinen Wohltaten, gefolgt von Perlen und Korallen, die aus ihnen hervorkommen."],
    ar: ["في سياق الآية المعروضة يلتقي بحران، فما الذي بينهما؟", ["حاجز لا يتعدّاه أيّ منهما", "جسر يعبر عليه المؤمنون", "سلسلة جبال تفصل بين أرضين", "نهر من نار يوم القيامة"], "يُرسل الله الماءين يلتقيان، ويمنع كلًّا منهما أن يطغى على الآخر بحاجز، وعدّت السورة ذلك من نعمه، ثم ذكرت ما يُستخرج منهما من الحلية."] },

  { id: "tfs-065", s: "tafsir", g: 3, d: 4, t: ["al-waqia", "purity-and-mushaf"], src: "Ibn Kathīr, Tafsīr, on 56:77–79; al-Qurṭubī, al-Jāmiʿ li-Aḥkām al-Qurʾān, on 56:79", v: "56:79",
    tr: ["comparative"],
    en: ["Which statement correctly describes the views on 'the purified' in the verse shown?", ["Many early authorities: the angels; others linked it to touching the muṣḥaf in purity", "All mufassirūn agree it means only people who have performed ghusl", "It was understood only of the prophets and never of the angels", "It refers to the scribes in Madīna who first wrote the muṣḥaf"], "Ibn ʿAbbās and others said only the angels touch the guarded Book in heaven. Others, citing the letter to ʿAmr ibn Ḥazm, take it as indicating that the muṣḥaf is touched only in purity; Ibn Kathīr mentions both lines of interpretation."],
    de: ["Welche Aussage beschreibt die Ansichten zu „den Gereinigten“ in der angezeigten Āya richtig?", ["Viele Frühe: die Engel; andere bezogen es auf das Berühren des Muṣḥaf in Reinheit", "Alle Kommentatoren meinen damit nur Menschen, die den Ġusl vollzogen haben", "Es wurde nur auf die Propheten bezogen und nie auf die Engel", "Gemeint sind die Schreiber in Medina, die den Muṣḥaf zuerst schrieben"], "Ibn ʿAbbās und andere sagten, nur die Engel berührten die bewahrte Schrift im Himmel. Andere, gestützt auf den Brief an ʿAmr ibn Ḥazm, sehen darin einen Hinweis, dass der Muṣḥaf nur in Reinheit berührt wird; Ibn Kaṯīr nennt beide Deutungen."],
    ar: ["أيّ العبارات تصف الأقوال في المطهّرين في الآية المعروضة وصفًا صحيحًا؟", ["الملائكة عند كثير من السلف، وربطه آخرون بمسّ المصحف على طهارة", "اتفق المفسرون على أنهم من اغتسل من الناس دون غيرهم", "لم يُفسَّر إلا بالأنبياء ولم يُحمل على الملائكة قط", "المراد الكتّاب في المدينة الذين كتبوا المصحف أول مرة"], "قال ابن عباس وغيره: لا يمسّ الكتاب المكنون في السماء إلا الملائكة، واستدل آخرون، مع كتاب عمرو بن حزم، على ألّا يمسّ المصحف إلا طاهر، وذكر ابن كثير الوجهين."] },

  { id: "tfs-066", s: "tafsir", g: 3, d: 3, t: ["al-hadid", "divine-names", "hadith-in-tafsir"], src: "Ibn Kathīr, Tafsīr, on 57:3; Muslim, Ṣaḥīḥ, Kitāb al-Dhikr wa-l-Duʿāʾ", v: "57:3",
    en: ["The four names in the verse shown (the First, the Last, the Manifest, the Hidden) are explained by the Prophet in a supplication in Ṣaḥīḥ Muslim. What does 'the First' mean there?", ["There is nothing before Him", "He was the first to be worshipped on earth", "He is first in rank among the angels", "He created the first human being"], "In the bedtime supplication reported by Muslim, the Prophet explained: the First, with nothing before Him; the Last, with nothing after Him; the Manifest, with nothing above Him; the Hidden, with nothing beneath Him."],
    de: ["Die vier Namen in der angezeigten Āya (der Erste, der Letzte, der Offenbare, der Verborgene) erklärt der Prophet in einem Bittgebet in Ṣaḥīḥ Muslim. Was bedeutet dort „der Erste“?", ["Vor Ihm ist nichts", "Er wurde als Erster auf Erden angebetet", "Er ist der Erste im Rang unter den Engeln", "Er erschuf den ersten Menschen"], "Im Bittgebet vor dem Schlafen bei Muslim erklärt der Prophet: der Erste, vor dem nichts ist; der Letzte, nach dem nichts ist; der Offenbare, über dem nichts ist; der Verborgene, unter dem nichts ist."],
    ar: ["فسّر النبي ﷺ الأسماء الأربعة في الآية المعروضة في دعاء رواه مسلم، فما معنى الأول فيه؟", ["لا شيء يسبقه في الوجود", "أول من عُبد في الأرض", "أول الملائكة رتبة", "خالق أول إنسان"], "في دعاء النوم الذي رواه مسلم بيّن النبي ﷺ أن الأول هو الذي لا يسبقه شيء، والآخر الذي لا يبقى شيء بعده، والظاهر الذي لا يعلوه شيء، والباطن الذي لا شيء أقرب منه."] },

  { id: "tfs-067", s: "tafsir", g: 3, d: 3, t: ["al-hadid", "hearts"], src: "Ibn Kathīr, Tafsīr, on 57:16", v: "57:16",
    en: ["What warning does the verse shown give the believers?", ["Not to become like earlier scripture-holders whose hearts hardened", "Not to build their houses higher than the walls of the mosque", "Not to keep trading once the call to Friday prayer is made", "Not to take spouses from among the People of the Book"], "The verse asks whether it is not time for believers' hearts to humble themselves at Allah's remembrance, and warns against becoming like those given the Book before, whose hearts hardened after a long time."],
    de: ["Welche Warnung richtet die angezeigte Āya an die Gläubigen?", ["Nicht wie frühere Schriftbesitzer zu werden, deren Herzen verhärteten", "Ihre Häuser nicht höher als die Mauern der Moschee zu bauen", "Nach dem Ruf zum Freitagsgebet nicht weiter Handel zu treiben", "Keine Ehepartner aus den Leuten der Schrift zu nehmen"], "Die Āya fragt, ob es nicht Zeit sei, dass die Herzen der Gläubigen sich beim Gedenken Allahs demütigen, und warnt davor, wie die früheren Schriftempfänger zu werden, deren Herzen nach langer Zeit hart wurden."],
    ar: ["ما التحذير الذي توجّهه الآية المعروضة إلى المؤمنين؟", ["ألّا يكونوا كمن سبقهم من أهل الكتاب في قسوة القلب", "ألّا يرفعوا بيوتهم فوق جدران المسجد", "ألّا يستمروا في البيع بعد النداء للجمعة", "ألّا يتزوجوا من نساء أهل الكتاب"], "تستحث الآية قلوب المؤمنين على الخشوع لذكر الله، وتحذّرهم أن يصيروا كأهل الكتاب من قبلهم الذين مرّت عليهم مدة طويلة فاشتدت قسوة قلوبهم."] },

  { id: "tfs-068", s: "tafsir", g: 3, d: 3, t: ["al-hashr", "quran-greatness"], src: "Ibn Kathīr, Tafsīr, on 59:21", v: "59:21",
    en: ["What image does the verse shown use to describe the greatness of the Quran?", ["A mountain would humble itself and split apart in awe of it", "The sea would turn to ink and run dry before its words end", "The stars would fall from the sky if it were recited", "The earth would shake each time it is read"], "If the Quran were sent down upon a mountain, the mountain would be humbled and split from fear of Allah; how then can human hearts remain unmoved? The image of the sea as ink belongs to 18:109."],
    de: ["Mit welchem Bild beschreibt die angezeigte Āya die Größe des Korans?", ["Ein Berg würde sich demütigen und aus Ehrfurcht spalten", "Das Meer würde zu Tinte und versiegen, bevor seine Worte enden", "Die Sterne fielen vom Himmel, wenn er rezitiert würde", "Die Erde bebte jedes Mal, wenn er gelesen wird"], "Würde der Koran auf einen Berg herabgesandt, würde dieser sich demütigen und aus Furcht vor Allah spalten; wie können menschliche Herzen dann ungerührt bleiben? Das Bild des Meeres als Tinte steht in 18:109."],
    ar: ["ما الصورة التي تصف بها الآية المعروضة عظمة القرآن؟", ["أن الجبل لو نزل عليه لذلّ وتشقق خوفًا", "أن البحر يصير مدادًا وينفد قبل كلماته", "أن النجوم تتساقط لو قُرئ", "أن الأرض ترجف كلما تُلي"], "لو أُنزل القرآن على جبل لذلّ وتشقق من الخوف من الله، فكيف تبقى قلوب البشر غير متأثرة؟ أما صورة البحر مدادًا ففي سورة الكهف."] },

  { id: "tfs-069", s: "tafsir", g: 3, d: 4, t: ["al-qadr", "laylat-al-qadr", "angels"], src: "Ibn Kathīr, Tafsīr, on 97:4; al-Ṭabarī, Jāmiʿ al-Bayān, on 97:4", v: "97:4",
    en: ["Who is 'the Spirit' (al-rūḥ) descending with the angels in the verse shown, according to most mufassirūn?", ["Jibrīl, mentioned separately to honour him", "The souls of the deceased believers", "The Quran in its entirety", "Mercy descending upon the earth"], "Most mufassirūn hold that al-rūḥ is Jibrīl, singled out after 'the angels' as a specific named after the general (ʿaṭf al-khāṣṣ ʿalā al-ʿāmm) to show his rank. Other views are reported, but this is the majority view."],
    de: ["Wer ist nach den meisten Kommentatoren „der Geist“ (ar-rūḥ), der in der angezeigten Āya mit den Engeln herabsteigt?", ["Ǧibrīl, gesondert genannt, um ihn zu ehren", "Die Seelen der verstorbenen Gläubigen", "Der Koran in seiner Gesamtheit", "Die Barmherzigkeit, die auf die Erde herabkommt"], "Die meisten Kommentatoren sagen, ar-rūḥ sei Ǧibrīl, nach „den Engeln“ als Besonderes nach dem Allgemeinen genannt (ʿaṭf al-ḫāṣṣ ʿalā al-ʿāmm), um seinen Rang zu zeigen. Es gibt weitere überlieferte Ansichten, doch dies ist die Mehrheitsmeinung."],
    ar: ["مَن الروح الذي يتنزّل مع الملائكة في الآية المعروضة عند أكثر المفسرين؟", ["جبريل، أُفرد بالذكر تشريفًا له", "أرواح المؤمنين المتوفين", "القرآن كله", "الرحمة النازلة على الأرض"], "عليه أكثر المفسرين أن الروح جبريل، عُطف على الملائكة من باب عطف الخاص على العام إظهارًا لشرفه، ورُويت أقوال أخرى، لكن هذا قول الجمهور."] },
  // ---------- stage 4 ----------
  { id: "tfs-070", s: "tafsir", g: 4, d: 5, t: ["al-kahf", "dhul-qarnayn", "mufassirun-views"], src: "Ibn Kathīr, Tafsīr, on 18:83; Ibn Kathīr, al-Bidāya wa-l-Nihāya, account of Dhū al-Qarnayn", v: "18:83",
    en: ["How does Ibn Kathīr treat the common identification of Dhū al-Qarnayn in the verse shown with Alexander of Macedon?", ["He rejects it: Alexander came much later and was not a believer", "He accepts it fully on the authority of the Greek historians", "He accepts it, adding that Alexander later embraced tawḥīd", "He leaves the question open without discussing Alexander at all"], "Ibn Kathīr distinguishes the Quranic Dhū al-Qarnayn, a righteous believing king of an earlier age, from Alexander the Macedonian, whose minister was Aristotle and who was a polytheist, and warns that confusing the two leads to serious error."],
    de: ["Wie behandelt Ibn Kaṯīr die verbreitete Gleichsetzung Ḏū al-Qarnains in der angezeigten Āya mit Alexander von Makedonien?", ["Er lehnt sie ab: Alexander lebte viel später und war kein Gläubiger", "Er übernimmt sie vollständig auf die Autorität griechischer Historiker", "Er übernimmt sie und fügt hinzu, Alexander sei später Monotheist geworden", "Er lässt die Frage offen, ohne Alexander überhaupt zu erörtern"], "Ibn Kaṯīr unterscheidet den koranischen Ḏū al-Qarnain, einen rechtschaffenen gläubigen König einer früheren Zeit, von Alexander dem Makedonier, dessen Wesir Aristoteles war und der Götzendiener war, und warnt, dass die Verwechslung zu schweren Fehlern führt."],
    ar: ["كيف يتعامل ابن كثير مع القول الشائع بأن ذا القرنين في الآية المعروضة هو الإسكندر المقدوني؟", ["يردّه: فالإسكندر متأخر جدًا ولم يكن مؤمنًا", "يقبله تمامًا اعتمادًا على مؤرخي اليونان", "يقبله ويذكر أن الإسكندر وحّد في آخر أمره", "يترك المسألة مفتوحة دون التعرض للإسكندر"], "يفرّق ابن كثير بين ذي القرنين المذكور في القرآن، وهو ملك مؤمن صالح من زمن متقدم، وبين الإسكندر المقدوني الذي كان أرسطو وزيره وكان مشركًا، وينبّه إلى أن الخلط بينهما يوقع في خطأ كبير."] },

  { id: "tfs-071", s: "tafsir", g: 4, d: 4, t: ["al-kahf", "musa-and-khidr"], src: "Ibn Kathīr, Tafsīr, on 18:80–81", v: "18:80",
    en: ["What reason does the verse shown give for the killing of the boy?", ["His believing parents might be driven by him to rebellion and disbelief", "He had already killed a man in the town the day before", "His own parents had asked al-Khiḍr to punish him for his crimes", "He was the son of the king who was seizing the boats by force"], "Al-Khiḍr explains that the boy's parents were believers and it was feared he would overwhelm them with rebellion and disbelief; the next verse says Allah would give them in exchange a child purer and more merciful. Ibn Kathīr cites the hadith in Ṣaḥīḥ Muslim that the boy was created a disbeliever."],
    de: ["Welchen Grund nennt die angezeigte Āya für die Tötung des Jungen?", ["Er hätte seine gläubigen Eltern zu Auflehnung und Unglauben getrieben", "Er hatte am Vortag bereits einen Mann in der Stadt getötet", "Seine eigenen Eltern hatten al-Ḫiḍr gebeten, ihn zu bestrafen", "Er war der Sohn des Königs, der die Boote gewaltsam nahm"], "Al-Ḫiḍr erklärt, die Eltern des Jungen seien gläubig gewesen und man habe gefürchtet, er würde sie mit Auflehnung und Unglauben überwältigen; die nächste Āya sagt, Allah werde ihnen dafür ein reineres und barmherzigeres Kind geben. Ibn Kaṯīr führt den Hadith in Ṣaḥīḥ Muslim an, wonach der Junge als Ungläubiger erschaffen war."],
    ar: ["ما السبب الذي تذكره الآية المعروضة لقتل الغلام؟", ["خُشي أن يحمل أبويه المؤمنين على التمرد والكفر", "كان قد قتل رجلًا في القرية في اليوم السابق", "طلب أبواه من الخضر أن يعاقبه على جرائمه", "كان ابن الملك الذي يغتصب السفن بالقوة"], "بيّن الخضر أن أبوي الغلام كانا مؤمنين فخُشي أن يحملهما على التمرد والكفر، وذكرت الآية بعدها أن الله يعوّضهما ولدًا أطهر وأكثر برًّا. وأورد ابن كثير حديث صحيح مسلم أن الغلام طُبع كافرًا."] },

  { id: "tfs-072", s: "tafsir", g: 4, d: 4, t: ["maryam", "hadith-in-tafsir"], src: "Ibn Kathīr, Tafsīr, on 19:96; al-Bukhārī and Muslim (hadith of Allah's love for a servant)", v: "19:96",
    en: ["With which well-known hadith does Ibn Kathīr explain the 'affection' (wudd) promised in the verse shown?", ["Allah loves a servant, informs Jibrīl, the heavens love him, and acceptance is placed for him on earth", "Whoever loves to meet Allah, Allah loves to meet him", "None of you truly believes until he loves for his brother what he loves for himself", "A person will be with those whom he loves"], "The verse promises that the Most Merciful will create affection for those who believe and do good. Ibn Kathīr explains it with the hadith in al-Bukhārī and Muslim: when Allah loves a servant He calls Jibrīl, the inhabitants of heaven love him, and acceptance is then placed for him on earth."],
    de: ["Mit welchem bekannten Hadith erklärt Ibn Kaṯīr die „Zuneigung“ (wudd), die in der angezeigten Āya versprochen wird?", ["Allah liebt einen Diener, sagt es Ǧibrīl, die Himmel lieben ihn, und auf Erden wird ihm Annahme gegeben", "Wer die Begegnung mit Allah liebt, dessen Begegnung liebt Allah", "Keiner glaubt wirklich, bis er seinem Bruder wünscht, was er sich selbst wünscht", "Der Mensch ist mit denen, die er liebt"], "Die Āya verspricht, dass der Allerbarmer denen, die glauben und Gutes tun, Zuneigung schaffen wird. Ibn Kaṯīr erklärt sie mit dem Hadith bei al-Buḫārī und Muslim: Liebt Allah einen Diener, ruft Er Ǧibrīl, die Bewohner des Himmels lieben ihn, und dann wird ihm Annahme auf Erden gegeben."],
    ar: ["بأيّ حديث مشهور فسّر ابن كثير الودّ الموعود في الآية المعروضة؟", ["حديث محبة الله لعبد ونداء جبريل ووضع القبول له في الأرض", "حديث محبة العبد لقاء ربه وجزاء ذلك", "حديث كمال الإيمان بحب الخير للأخ المسلم", "حديث كون المرء مع من يحبه يوم القيامة"], "تعد الآية المؤمنين العاملين للصالحات بأن يجعل الرحمن لهم محبة، وفسّرها ابن كثير بحديث الصحيحين في أن الله إذا أحب عبدًا نادى جبريل فأحبه أهل السماء ثم يوضع له القبول في الأرض."] },

  { id: "tfs-073", s: "tafsir", g: 4, d: 4, t: ["ta-ha", "muqattaat", "mufassirun-views"], src: "Ibn Kathīr, Tafsīr, on 20:1; al-Qurṭubī, al-Jāmiʿ li-Aḥkām al-Qurʾān, on 20:1", v: "20:1",
    en: ["Which statement correctly describes the views on the opening of Sūrat Ṭā Hā shown?", ["Many: disjointed letters; Ibn ʿAbbās and others: 'O man' in a dialect", "All agree it is a name of the Prophet used only in this surah", "All agree it means 'pure guidance' in the classical Arabic tongue", "The Companions read it as a command to stand up for prayer"], "Ibn Kathīr discusses it with the other disjointed letters, and also reports from Ibn ʿAbbās, Mujāhid, Saʿīd ibn Jubayr and others that it means 'O man' (in Nabatean or another dialect). Its use as a name of the Prophet is a later popular view, not a consensus."],
    de: ["Welche Aussage beschreibt die Ansichten zum angezeigten Anfang der Sūrat Ṭā Hā richtig?", ["Viele: Einzelbuchstaben; Ibn ʿAbbās und andere: „O Mann“ in einem Dialekt", "Alle sehen darin einen nur hier genannten Namen des Propheten", "Alle deuten es als „reine Rechtleitung“ im klassischen Arabisch", "Die Gefährten lasen es als Befehl, sich zum Gebet zu erheben"], "Ibn Kaṯīr behandelt es mit den anderen Einzelbuchstaben und überliefert zudem von Ibn ʿAbbās, Muǧāhid, Saʿīd ibn Ǧubair und anderen, es bedeute „O Mann“ (im Nabatäischen oder einem anderen Dialekt). Die Verwendung als Name des Propheten ist eine spätere volkstümliche Ansicht, kein Konsens."],
    ar: ["أيّ العبارات تصف الأقوال في مطلع سورة طه المعروض وصفًا صحيحًا؟", ["كثيرون: حروف مقطعة، وعن ابن عباس وغيره: يا رجل بلغة أخرى", "اتفقوا على أنه اسم للنبي ﷺ لم يرد إلا هنا", "اتفقوا على أن معناه الهدى الخالص بالفصحى", "قرأه الصحابة أمرًا بالقيام إلى الصلاة"], "تناوله ابن كثير مع سائر الحروف المقطعة، وروى عن ابن عباس ومجاهد وسعيد بن جبير وغيرهم أن معناه يا رجل بالنبطية أو غيرها، أما جعله اسمًا للنبي ﷺ فقول شائع متأخر لا إجماع عليه."] },

  { id: "tfs-074", s: "tafsir", g: 4, d: 4, t: ["al-nur", "mosques"], src: "Ibn Kathīr, Tafsīr, on 24:36–37", v: "24:36",
    en: ["According to Ibn ʿAbbās and most mufassirūn, what are the 'houses' that Allah permitted to be raised in the verse shown?", ["The mosques", "The homes of the Prophet's wives", "The houses of the Companions in Madīna", "The houses of the People of the Book"], "Directly after the Light Verse, the passage speaks of houses in which His name is remembered and glorified morning and evening by men whom trade does not distract; Ibn Kathīr reports from Ibn ʿAbbās, Mujāhid and others that these are the mosques."],
    de: ["Was sind nach Ibn ʿAbbās und den meisten Kommentatoren die „Häuser“, deren Errichtung Allah in der angezeigten Āya erlaubt hat?", ["Die Moscheen", "Die Wohnungen der Frauen des Propheten", "Die Häuser der Gefährten in Medina", "Die Häuser der Leute der Schrift"], "Unmittelbar nach dem Lichtvers spricht der Abschnitt von Häusern, in denen Sein Name morgens und abends von Männern gepriesen wird, die kein Handel ablenkt; Ibn Kaṯīr überliefert von Ibn ʿAbbās, Muǧāhid und anderen, dass die Moscheen gemeint sind."],
    ar: ["ما البيوت التي أذن الله أن تُرفع في الآية المعروضة عند ابن عباس وأكثر المفسرين؟", ["المساجد", "حجرات أزواج النبي ﷺ", "بيوت الصحابة في المدينة", "بيوت أهل الكتاب"], "بعد آية النور مباشرة تذكر الآيات بيوتًا يُذكر فيها اسم الله ويسبّحه فيها صباحًا ومساءً رجال لا تشغلهم التجارة، وروى ابن كثير عن ابن عباس ومجاهد وغيرهما أنها المساجد."] },

  { id: "tfs-075", s: "tafsir", g: 4, d: 5, t: ["al-furqan", "ibad-al-rahman", "quranic-vocabulary"], src: "Ibn Kathīr, Tafsīr, on 25:63", v: "25:63",
    en: ["According to Ibn Kathīr, what does the 'gentle' walk (hawn) of the servants of the Most Merciful in the verse shown mean?", ["Calm dignity without arrogance, not an affected sickly gait", "Walking slowly and weakly as a display of humility", "Keeping always to the edges of the road when walking", "Avoiding the markets and walking only to the mosque"], "Ibn Kathīr explains hawnan as tranquillity and dignity, free of tyranny and pride, and stresses that it does not mean walking like the sick out of affectation and show; he notes the Prophet walked briskly, as if descending a slope."],
    de: ["Was bedeutet nach Ibn Kaṯīr der „sanfte“ Gang (hawn) der Diener des Allerbarmers in der angezeigten Āya?", ["Ruhige Würde ohne Hochmut, kein gekünstelter Krankengang", "Langsames, schwaches Gehen als Zeichen der Demut", "Beim Gehen stets am Rand des Weges zu bleiben", "Die Märkte zu meiden und nur zur Moschee zu gehen"], "Ibn Kaṯīr erklärt hawnan als Gelassenheit und Würde ohne Gewalttätigkeit und Stolz und betont, dass kein gekünstelter Gang wie der eines Kranken gemeint ist; er bemerkt, dass der Prophet zügig ging, als stiege er einen Hang hinab."],
    ar: ["ما معنى المشي هونًا لعباد الرحمن في الآية المعروضة عند ابن كثير؟", ["سكينة ووقار بلا تكبر ولا تماوت متصنّع", "المشي ببطء وضعف إظهارًا للتواضع", "التزام أطراف الطريق دائمًا عند المشي", "ترك الأسواق والمشي إلى المسجد فقط"], "فسّر ابن كثير الهون بالسكينة والوقار من غير جبروت ولا استكبار، ونبّه إلى أنه ليس المشي كالمرضى تصنّعًا ورياءً، وذكر أن النبي ﷺ كان إذا مشى كأنما ينحدر من مرتفع."] },

  { id: "tfs-076", s: "tafsir", g: 4, d: 5, t: ["al-furqan", "ibad-al-rahman", "mufassirun-views"], src: "Ibn Kathīr, Tafsīr, on 25:72; al-Ṭabarī, Jāmiʿ al-Bayān, on 25:72", v: "25:72",
    tr: ["comparative"],
    en: ["Which statement correctly describes the views on al-zūr that the servants of the Most Merciful do not witness in the verse shown?", ["Several views (shirk, pagan feasts, lies, false testimony); many read it broadly", "All mufassirūn restricted it to false testimony given before a judge", "All mufassirūn restricted it to listening to musical instruments", "It was explained only as the mosque built by the hypocrites"], "Ibn Kathīr reports that some said al-zūr is shirk and idol worship, others the polytheists' festivals, others lying and sinful gatherings, and others false testimony. Al-Ṭabarī preferred taking it generally as attending every kind of falsehood."],
    de: ["Welche Aussage beschreibt die Ansichten über az-zūr, dem die Diener des Allerbarmers in der angezeigten Āya nicht beiwohnen, richtig?", ["Mehrere Ansichten (Schirk, Götzenfeste, Lüge, Falschzeugnis); viele fassten es weit", "Alle Kommentatoren beschränkten es auf falsches Zeugnis vor einem Richter", "Alle Kommentatoren beschränkten es auf das Hören von Musikinstrumenten", "Es wurde nur als die von den Heuchlern gebaute Moschee erklärt"], "Ibn Kaṯīr berichtet: Manche sagten, az-zūr sei Schirk und Götzendienst, andere die Feste der Götzendiener, andere Lüge und sündhafte Versammlungen, andere falsches Zeugnis. Aṭ-Ṭabarī zog die allgemeine Deutung vor, nämlich jede Art von Nichtigem zu meiden."],
    ar: ["أيّ العبارات تصف الأقوال في الزور الذي لا يشهده عباد الرحمن في الآية المعروضة وصفًا صحيحًا؟", ["أقوال: الشرك وأعياد المشركين والكذب وشهادة الزور، وعمّمه كثيرون", "قصره المفسرون جميعًا على شهادة الزور أمام القاضي", "قصره المفسرون جميعًا على سماع المعازف وآلات اللهو", "لم يُفسَّر إلا بالمسجد الذي بناه المنافقون"], "نقل ابن كثير أن من السلف من قال الزور الشرك وعبادة الأصنام، ومنهم من قال أعياد المشركين، ومنهم من قال الكذب ومجالس الفسق، ومنهم من قال شهادة الزور، واختار الطبري العموم في كل باطل."] },

  { id: "tfs-077", s: "tafsir", g: 4, d: 4, t: ["luqman", "mufassirun-views"], src: "Ibn Kathīr, Tafsīr, on 31:12", v: "31:12",
    en: ["The verse shown says Luqmān was given wisdom. What is the majority view of the salaf about his status, as reported by Ibn Kathīr?", ["He was a wise, righteous servant, not a prophet", "He was a prophet sent to the people of Egypt", "He was a messenger with a revealed book", "He was one of the angels sent in human form"], "Ibn Kathīr notes that the salaf differed on whether Luqmān was a prophet, and that most held he was a righteous servant given wisdom without prophethood; the opposite view is reported from ʿIkrima."],
    de: ["Die angezeigte Āya sagt, Luqmān sei Weisheit gegeben worden. Welche Mehrheitsmeinung der Salaf zu seinem Rang berichtet Ibn Kaṯīr?", ["Er war ein weiser, rechtschaffener Diener, kein Prophet", "Er war ein zu den Ägyptern gesandter Prophet", "Er war ein Gesandter mit offenbarter Schrift", "Er war ein Engel in Menschengestalt"], "Ibn Kaṯīr bemerkt, dass die Salaf uneins waren, ob Luqmān Prophet war, und die meisten meinten, er sei ein rechtschaffener Diener gewesen, dem Weisheit ohne Prophetentum gegeben wurde; die Gegenansicht wird von ʿIkrima überliefert."],
    ar: ["تذكر الآية المعروضة أن لقمان أوتي الحكمة، فما قول أكثر السلف في منزلته كما نقله ابن كثير؟", ["أنه عبد صالح حكيم وليس نبيًا", "أنه نبي أُرسل إلى أهل مصر", "أنه رسول أُنزل عليه كتاب", "أنه ملك تمثّل بشرًا"], "ذكر ابن كثير أن السلف اختلفوا في نبوة لقمان، وأن أكثرهم على أنه عبد صالح أوتي الحكمة من غير نبوة، ونُقل القول بنبوته عن عكرمة."] },

  { id: "tfs-078", s: "tafsir", g: 4, d: 4, t: ["luqman", "tawhid", "hadith-in-tafsir"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb al-Īmān (hadith of Ibn Masʿūd); Ibn Kathīr, Tafsīr, on 31:13", v: "31:13",
    en: ["According to the hadith of Ibn Masʿūd in Ṣaḥīḥ al-Bukhārī, how did the Prophet use the verse shown?", ["To show that the 'wrong' in 6:82 means shirk", "To prove that every sin cancels a person's faith", "To show that Luqmān had been sent as a prophet", "To permit obeying one's parents in disbelief"], "When 6:82 was revealed (those who do not mix their faith with wrong are safe), the Companions were troubled, since everyone wrongs himself. The Prophet clarified that the wrong meant is shirk, citing Luqmān's words in the verse shown. It is a classic case of tafsīr of Quran by Quran through the Sunna."],
    de: ["Wie verwendete der Prophet die angezeigte Āya nach dem Hadith Ibn Masʿūds in Ṣaḥīḥ al-Buḫārī?", ["Um zu zeigen, dass das „Unrecht“ in 6:82 Schirk ist", "Um zu beweisen, dass jede Sünde den Glauben aufhebt", "Um zu zeigen, dass Luqmān als Prophet gesandt war", "Um Gehorsam gegenüber Eltern im Unglauben zu erlauben"], "Als 6:82 offenbart wurde (wer seinen Glauben nicht mit Unrecht vermischt, ist sicher), waren die Gefährten bestürzt, denn jeder tut sich Unrecht. Der Prophet stellte klar, dass Schirk gemeint ist, und zitierte Luqmāns Worte aus der angezeigten Āya – ein klassischer Fall der Auslegung des Korans durch den Koran mittels der Sunna."],
    ar: ["كيف استعمل النبي ﷺ الآية المعروضة بحسب حديث ابن مسعود في صحيح البخاري؟", ["لبيان أن الظلم في آية الأنعام هو الشرك", "للاستدلال على أن كل معصية تنقض الإيمان", "لإثبات أن لقمان كان نبيًا مرسلًا", "لإباحة طاعة الوالدين في الكفر"], "لما نزلت آية الأنعام في الأمن لمن لم يخلط إيمانه بظلم شقّ ذلك على الصحابة، إذ لا يخلو أحد من ظلم نفسه، فبيّن النبي ﷺ أن المراد الشرك واستشهد بقول لقمان في الآية المعروضة، وهذا من تفسير القرآن بالقرآن ببيان السنة."] },

  { id: "tfs-079", s: "tafsir", g: 4, d: 5, t: ["ya-sin", "mufassirun-views", "accountability"], src: "Ibn Kathīr, Tafsīr, on 36:12; Muslim, Ṣaḥīḥ, Kitāb al-Masājid (hadith of Banū Salima)", v: "36:12",
    en: ["How does Ibn Kathīr treat the two explanations of the 'traces' (āthār) that are recorded in the verse shown?", ["He reports both, effects of deeds and footsteps, and sees no conflict", "He accepts only the footsteps and rejects the other view as weak", "He accepts only the effects and sets aside the Banū Salima report", "He says it means the ruins left behind by destroyed nations"], "One view: what people leave behind of good or bad practices that others follow, supported by the hadith on initiating a good or bad sunna. The other: their footsteps, as in the hadith of Banū Salima who wished to move near the mosque. Ibn Kathīr says the second meaning is included in the first, so there is no contradiction."],
    de: ["Wie behandelt Ibn Kaṯīr die zwei Erklärungen der „Spuren“ (āṯār), die in der angezeigten Āya aufgezeichnet werden?", ["Er nennt beide, Folgen der Taten und Schritte, ohne Widerspruch", "Er nimmt nur die Schritte an und verwirft die andere Ansicht", "Er nimmt nur die Folgen an und lässt den Bericht der Banū Salima beiseite", "Er sagt, gemeint seien die Ruinen vernichteter Völker"], "Eine Ansicht: was Menschen an guten oder schlechten Gepflogenheiten hinterlassen, denen andere folgen, gestützt auf den Hadith über das Einführen einer guten oder schlechten Sunna. Die andere: ihre Schritte, wie im Hadith der Banū Salima, die näher an die Moschee ziehen wollten. Ibn Kaṯīr sagt, die zweite Bedeutung sei in der ersten enthalten, also kein Widerspruch."],
    ar: ["كيف تعامل ابن كثير مع التفسيرين للآثار المكتوبة في الآية المعروضة؟", ["ذكر القولين، أثر الأعمال والخطى، ولا تعارض بينهما", "قبل الخطى وحدها وضعّف القول الآخر", "قبل أثر الأعمال وحده وترك خبر بني سلمة", "قال إن المراد أطلال الأمم المهلكة"], "قيل: الآثار ما يتركه الناس من سنن حسنة أو سيئة يُعمل بها بعدهم، ويشهد له حديث سنّ السنن الحسنة والسيئة. وقيل: خطاهم، كما في حديث بني سلمة حين أرادوا الانتقال قرب المسجد. وذكر ابن كثير أن المعنى الثاني داخل في الأول فلا تعارض."] },

  { id: "tfs-080", s: "tafsir", g: 4, d: 4, t: ["al-hujurat", "manners-with-the-prophet", "asbab-al-nuzul"], src: "Ibn Kathīr, Tafsīr, on 49:2; al-Bukhārī and Muslim (hadith of Anas on Thābit ibn Qays)", v: "49:2",
    en: ["Which Companion, known for his loud voice, stayed at home in fear after the verse shown was revealed, until the Prophet said he was of the people of Paradise?", ["Thābit ibn Qays ibn Shammās", "Saʿd ibn Muʿādh", "Ubayy ibn Kaʿb", "Ḥassān ibn Thābit"], "The verse forbids raising voices above the Prophet's lest one's deeds be nullified unknowingly. Thābit ibn Qays, the orator of the Anṣār, feared it applied to him; the Prophet sent word that he was not of the people of the Fire but of Paradise, as narrated by Anas in the Ṣaḥīḥayn."],
    de: ["Welcher Gefährte, bekannt für seine laute Stimme, blieb nach der Offenbarung der angezeigten Āya aus Furcht zu Hause, bis der Prophet sagte, er gehöre zu den Leuten des Paradieses?", ["Ṯābit ibn Qais ibn Šammās", "Saʿd ibn Muʿāḏ", "Ubayy ibn Kaʿb", "Ḥassān ibn Ṯābit"], "Die Āya verbietet, die Stimme über die des Propheten zu erheben, damit die eigenen Taten nicht unbemerkt nichtig werden. Ṯābit ibn Qais, der Redner der Anṣār, fürchtete, es gelte ihm; der Prophet ließ ihm ausrichten, er gehöre nicht zu den Leuten des Feuers, sondern des Paradieses, wie Anas in den beiden Ṣaḥīḥ berichtet."],
    ar: ["أيّ الصحابة، وكان جهير الصوت، لزم بيته خوفًا بعد نزول الآية المعروضة حتى أخبره النبي ﷺ أنه من أهل الجنة؟", ["ثابت بن قيس بن شماس", "سعد بن معاذ", "أبي بن كعب", "حسان بن ثابت"], "تنهى الآية عن رفع الصوت فوق صوت النبي ﷺ خشية أن تبطل الأعمال دون أن يدري صاحبها، فخاف ثابت بن قيس خطيب الأنصار أن يكون المعنيّ، فبشّره النبي ﷺ بأنه ليس من أهل النار بل من أهل الجنة، كما في حديث أنس في الصحيحين."] },

  { id: "tfs-081", s: "tafsir", g: 4, d: 5, t: ["al-rahman", "paradise", "mufassirun-views"], src: "Ibn Kathīr, Tafsīr, on 55:46 and 55:62; al-Bukhārī, Ṣaḥīḥ, Kitāb al-Tafsīr (hadith of Abū Mūsā)", v: "55:62",
    en: ["Al-Raḥmān mentions two gardens for the one who fears standing before his Lord, then in the verse shown two more. How does Ibn Kathīr relate the two pairs?", ["The second pair ranks below the first (gold versus silver gardens)", "The second pair ranks higher and is for the prophets alone", "Both pairs are the same gardens, described twice for emphasis", "The second pair is reserved for the believing jinn only"], "Ibn Kathīr holds that the gardens in the verse shown are below the first two in virtue and rank, and links this to the hadith of Abū Mūsā in al-Bukhārī about two gardens of silver and two of gold. The first pair is for the ones brought near, the second for the people of the right."],
    de: ["Ar-Raḥmān nennt zwei Gärten für den, der das Stehen vor seinem Herrn fürchtet, und in der angezeigten Āya zwei weitere. Wie setzt Ibn Kaṯīr die beiden Paare zueinander in Beziehung?", ["Das zweite Paar steht unter dem ersten (Gärten aus Gold und Silber)", "Das zweite Paar steht höher und ist allein für die Propheten", "Beide Paare sind dieselben Gärten, zweimal zur Betonung beschrieben", "Das zweite Paar ist allein den gläubigen Dschinn vorbehalten"], "Ibn Kaṯīr meint, die Gärten der angezeigten Āya stünden an Vorzug und Rang unter den ersten beiden, und verbindet dies mit dem Hadith von Abū Mūsā bei al-Buḫārī über zwei Gärten aus Silber und zwei aus Gold. Das erste Paar ist für die Nahegebrachten, das zweite für die Leute der Rechten."],
    ar: ["تذكر سورة الرحمن جنتين لمن يخشى وقوفه بين يدي ربه، ثم جنتين أخريين في الآية المعروضة، فكيف ربط ابن كثير بين الزوجين؟", ["الثانيتان دون الأوليين، كجنتي الذهب وجنتي الفضة", "الثانيتان أعلى منزلة وهما للأنبياء خاصة", "هما الجنتان نفسهما وُصفتا مرتين للتأكيد", "الثانيتان خاصتان بمؤمني الجن وحدهم"], "يرى ابن كثير أن الجنتين في الآية المعروضة دون الأوليين فضلًا ومنزلة، واستشهد بحديث أبي موسى في البخاري في جنتين من فضة وجنتين من ذهب، فالأوليان للمقربين والأخريان لأصحاب اليمين."] },

  { id: "tfs-082", s: "tafsir", g: 4, d: 5, t: ["al-waqia", "mufassirun-views", "quranic-vocabulary"], src: "Ibn Kathīr, Tafsīr, on 56:75–76; al-Ṭabarī, Jāmiʿ al-Bayān, on 56:75", v: "56:75",
    tr: ["comparative"],
    en: ["Which statement correctly describes the views on the 'positions of the stars' (mawāqiʿ al-nujūm) sworn by in the verse shown?", ["Mujāhid: the stars' setting places; Ibn ʿAbbās: the Quran's instalments", "All agreed it means the twelve constellations of the zodiac", "All agreed it means the stars that fall at the Resurrection", "It was explained only as the stations where angels stand"], "Ibn Kathīr reports Mujāhid's view that it refers to the rising and setting points of the stars, and from Ibn ʿAbbās that it refers to the parts (nujūm) of the Quran sent down gradually, which fits the following verses about the noble Quran. Al-Ḥasan is reported to have referred it to their scattering at the Hour."],
    de: ["Welche Aussage beschreibt die Ansichten zu den „Standorten der Sterne“ (mawāqiʿ an-nuǧūm), bei denen in der angezeigten Āya geschworen wird, richtig?", ["Muǧāhid: Untergangsorte der Sterne; Ibn ʿAbbās: die Teile des Korans", "Alle verstanden darunter die zwölf Sternbilder des Tierkreises", "Alle verstanden darunter die bei der Auferstehung fallenden Sterne", "Es wurde nur als die Standorte der Engel erklärt"], "Ibn Kaṯīr überliefert von Muǧāhid, gemeint seien die Auf- und Untergangsorte der Sterne, und von Ibn ʿAbbās, gemeint seien die Teile (nuǧūm) des stufenweise herabgesandten Korans, was zu den folgenden Āyāt über den edlen Koran passt. Von al-Ḥasan wird ihr Zerstreuen bei der Stunde berichtet."],
    ar: ["أيّ العبارات تصف الأقوال في مواقع النجوم المقسم بها في الآية المعروضة وصفًا صحيحًا؟", ["مجاهد: مغارب النجوم، وابن عباس: نجوم القرآن المنزّل مفرّقًا", "اتفقوا على أنها البروج الاثنا عشر في السماء", "اتفقوا على أنها النجوم المتساقطة يوم القيامة", "لم تُفسَّر إلا بمقامات الملائكة في السماء"], "نقل ابن كثير عن مجاهد أنها مطالع النجوم ومغاربها، وعن ابن عباس أنها نجوم القرآن المنزّل منجّمًا، وهو يناسب ما بعدها من وصف القرآن الكريم، ورُوي عن الحسن أنها انتثارها يوم القيامة."] },

  { id: "tfs-083", s: "tafsir", g: 4, d: 5, t: ["al-hadid", "companions", "mufassirun-views"], src: "Ibn Kathīr, Tafsīr, on 57:10", v: "57:10",
    tr: ["comparative"],
    en: ["The verse shown says those who spent and fought before 'the victory' (al-fatḥ) are not equal to those who did so later. Which statement correctly describes the views on this fatḥ?", ["Most: the conquest of Makka; al-Shaʿbī and others: al-Ḥudaybiya", "All agreed that it refers to the Battle of Badr", "All agreed that it refers to the conquest of Khaybar", "Most said the Trench, and none named al-Ḥudaybiya"], "Ibn Kathīr reports that the majority understood al-fatḥ here as the conquest of Makka, while al-Shaʿbī and others said al-Ḥudaybiya, which is also called a clear victory in Sūrat al-Fatḥ. Either way, the verse ranks the earlier believers higher, while promising good to both."],
    de: ["Die angezeigte Āya sagt, wer vor „dem Sieg“ (al-fatḥ) ausgegeben und gekämpft hat, sei nicht gleich denen, die es später taten. Welche Aussage beschreibt die Ansichten zu diesem fatḥ richtig?", ["Die meisten: Eroberung Mekkas; aš-Šaʿbī und andere: al-Ḥudaibiya", "Alle waren sich einig, es sei die Schlacht von Badr", "Alle waren sich einig, es sei die Eroberung Ḫaibars", "Die meisten: die Grabenschlacht; niemand nannte al-Ḥudaibiya"], "Ibn Kaṯīr berichtet, dass die Mehrheit al-fatḥ hier als die Eroberung Mekkas verstand, während aš-Šaʿbī und andere al-Ḥudaibiya nannten, die in Sūrat al-Fatḥ ebenfalls als offenkundiger Sieg bezeichnet wird. In jedem Fall stellt die Āya die früheren Gläubigen höher und verspricht beiden Gutes."],
    ar: ["تقرّر الآية المعروضة أن من بذل المال وجاهد قبل الفتح لا يساوي من فعل ذلك بعده، فأيّ العبارات تصف الأقوال في هذا الفتح وصفًا صحيحًا؟", ["قال الأكثرون فتح مكة، وقال الشعبي وغيره صلح الحديبية", "اتفقوا على أنه غزوة بدر", "اتفقوا على أنه فتح خيبر", "قال الأكثرون غزوة الخندق ولم يذكر أحد الحديبية"], "نقل ابن كثير أن الجمهور على أن الفتح هنا فتح مكة، وعن الشعبي وغيره أنه صلح الحديبية الذي سُمّي فتحًا ظاهرًا في سورة الفتح، وعلى القولين ففضل السابقين ثابت مع وعد الفريقين بالجزاء الحسن."] },

  { id: "tfs-084", s: "tafsir", g: 4, d: 5, t: ["maryam", "day-of-judgement", "mufassirun-views"], src: "Ibn Kathīr, Tafsīr, on 19:71–72; al-Ṭabarī, Jāmiʿ al-Bayān, on 19:71", v: "19:71",
    tr: ["comparative"],
    en: ["Which statement correctly describes the classical views on the 'coming to it' (wurūd) of Hell mentioned in the verse shown?", ["Ibn Masʿūd: passing over the Ṣirāṭ; Ibn ʿAbbās: entering it", "All agreed it applies to the disbelievers alone", "All agreed it means only seeing Hell from far away", "It was understood only of the hypocrites of Madīna"], "Ibn Kathīr reports that Ibn Masʿūd and others explained wurūd as passing over the bridge above Hell, each according to his deeds, while Ibn ʿAbbās is reported to have said it means entering. On both views, the next verse states that Allah saves the God-fearing and leaves the wrongdoers in it."],
    de: ["Welche Aussage beschreibt die klassischen Ansichten zum „Hingelangen“ (wurūd) zur Hölle in der angezeigten Āya richtig?", ["Ibn Masʿūd: Überqueren des Ṣirāṭ; Ibn ʿAbbās: Betreten", "Alle sahen darin nur die Ungläubigen betroffen", "Alle verstanden es nur als Sehen der Hölle aus der Ferne", "Es wurde nur auf die Heuchler Medinas bezogen"], "Ibn Kaṯīr berichtet, Ibn Masʿūd und andere erklärten wurūd als das Überqueren der Brücke über der Hölle, jeder nach seinen Taten, während von Ibn ʿAbbās das Betreten überliefert wird. Nach beiden Ansichten sagt die nächste Āya, dass Allah die Gottesfürchtigen rettet und die Ungerechten darin lässt."],
    ar: ["أيّ العبارات تصف أقوال السلف في الورود المذكور في الآية المعروضة وصفًا صحيحًا؟", ["ابن مسعود: المرور على الصراط، وابن عباس: الدخول", "اتفقوا على أنه خاص بالكافرين وحدهم", "اتفقوا على أنه مجرد رؤيتها من بعيد", "لم يُحمل إلا على منافقي المدينة"], "نقل ابن كثير عن ابن مسعود وغيره أن الورود المرور على الصراط المنصوب فوق جهنم كلٌّ بحسب عمله، ورُوي عن ابن عباس أنه الدخول، وعلى القولين تخبر الآية التالية أن الله يخلّص أهل التقوى ويُبقي الظالمين فيها."] },

  { id: "tfs-085", s: "tafsir", g: 4, d: 4, t: ["al-ikhlas", "divine-names", "quranic-vocabulary"], src: "Ibn Kathīr, Tafsīr, on 112:2; al-Ṭabarī, Jāmiʿ al-Bayān, on 112:2", v: "112:2",
    en: ["Which of the following is among the classical explanations of al-Ṣamad in the verse shown?", ["The Master to whom all creatures turn in their needs", "The First, before whom there is nothing", "The Light of the heavens and the earth", "The One who covers the sins of His servants"], "Ibn ʿAbbās explained al-Ṣamad as the one to whom creatures turn in their needs and the Master perfect in all attributes; others, such as Ibn Masʿūd, said the one who has no hollow (does not eat or drink). The distractors describe other names (al-Awwal, al-Nūr, al-Ghafūr)."],
    de: ["Welche der folgenden gehört zu den klassischen Erklärungen von aṣ-Ṣamad in der angezeigten Āya?", ["Der Herr, an den sich alle in ihren Nöten wenden", "Der Erste, vor dem nichts ist", "Das Licht der Himmel und der Erde", "Der die Sünden Seiner Diener bedeckt"], "Ibn ʿAbbās erklärte aṣ-Ṣamad als den, an den sich die Geschöpfe in ihren Nöten wenden, und als den in allen Eigenschaften vollkommenen Herrn; andere, etwa Ibn Masʿūd, sagten: der keinen Hohlraum hat (nicht isst und trinkt). Die Ablenker beschreiben andere Namen (al-Awwal, an-Nūr, al-Ġafūr)."],
    ar: ["أيّ مما يلي من التفسيرات المأثورة للصمد في الآية المعروضة؟", ["السيد الذي تقصده الخلائق في حوائجها", "الأول الذي لا يسبقه شيء", "الهادي بنوره أهل السماوات والأرض", "الذي يستر ذنوب عباده"], "فسّر ابن عباس الصمد بالذي تصمد إليه الخلائق في حوائجها والسيد الكامل في صفاته، وقال آخرون كابن مسعود: الذي لا جوف له فلا يأكل ولا يشرب. أما الخيارات الأخرى فأوصاف لأسماء أخرى كالأول والنور والغفور."] },

  { id: "tfs-086", s: "tafsir", g: 4, d: 4, t: ["muawwidhatan", "sorcery"], src: "Ibn Kathīr, Tafsīr, on 113:4; al-Bukhārī, Ṣaḥīḥ, Kitāb al-Ṭibb (hadith of the sorcery of Labīd ibn al-Aʿṣam)", v: "113:4",
    en: ["Who are 'those who blow on knots' in the verse shown, according to Mujāhid, ʿIkrima, al-Ḥasan and Qatāda?", ["Women who practise sorcery", "Women spinning thread at night", "Poets who recite satire against the Prophet", "Soothsayers who read the stars"], "These early mufassirūn explain al-naffāthāt as sorceresses who blow while tying knots. The mufassirūn connect the two surahs of refuge with the sorcery of Labīd ibn al-Aʿṣam against the Prophet, reported in al-Bukhārī and Muslim; the explicit link to the surahs is found in other narrations."],
    de: ["Wer sind „die, die auf Knoten blasen“ in der angezeigten Āya nach Muǧāhid, ʿIkrima, al-Ḥasan und Qatāda?", ["Frauen, die Zauberei betreiben", "Frauen, die nachts Garn spinnen", "Dichter, die Spottverse gegen den Propheten vortragen", "Wahrsager, die die Sterne deuten"], "Diese frühen Kommentatoren erklären an-naffāṯāt als Zauberinnen, die beim Knüpfen von Knoten blasen. Die Kommentatoren verbinden die beiden Zufluchtsuren mit der Zauberei Labīd ibn al-Aʿṣams gegen den Propheten, die al-Buḫārī und Muslim berichten; die ausdrückliche Verbindung mit den Suren steht in anderen Überlieferungen."],
    ar: ["مَن النافخات على العقد المذكورات في الآية المعروضة عند مجاهد وعكرمة والحسن وقتادة؟", ["النساء الساحرات", "النساء اللواتي يغزلن ليلًا", "الشعراء الذين يهجون النبي ﷺ", "الكهان الذين يقرؤون النجوم"], "فسّر هؤلاء السلف النفاثات بالسواحر اللاتي ينفثن عند عقد العقد، وربط المفسرون المعوذتين بسحر لبيد بن الأعصم للنبي ﷺ المروي في الصحيحين، وإنما جاء التصريح بربطه بالسورتين في روايات أخرى."] },

  { id: "tfs-087", s: "tafsir", g: 4, d: 4, t: ["al-kawthar", "asbab-al-nuzul"], src: "Ibn Kathīr, Tafsīr, on 108:3", v: "108:3",
    en: ["What is the point of the verse shown, given the occasion reported by Ibn ʿAbbās and others?", ["The enemy who called him 'cut off' is himself cut off", "The Prophet would leave no descendants of any kind", "The Prophet should break ties with his hostile relatives", "Quraysh would soon be cut off from their trade routes"], "When the Prophet's sons died, an opponent (commonly named as al-ʿĀṣ ibn Wāʾil) mocked him as abtar, without a male heir. The surah answers that it is his hater who is cut off from good and remembrance, while the Prophet's name and message endure."],
    de: ["Worum geht es in der angezeigten Āya angesichts des von Ibn ʿAbbās und anderen überlieferten Anlasses?", ["Der Feind, der ihn „abgeschnitten“ nannte, ist selbst abgeschnitten", "Der Prophet werde keinerlei Nachkommen hinterlassen", "Der Prophet solle mit seinen feindlichen Verwandten brechen", "Die Quraisch würden bald von ihren Handelswegen abgeschnitten"], "Als die Söhne des Propheten starben, verspottete ihn ein Gegner (meist al-ʿĀṣ ibn Wāʾil genannt) als abtar, ohne männlichen Erben. Die Sure antwortet, dass sein Hasser vom Guten und vom Gedenken abgeschnitten ist, während Name und Botschaft des Propheten bleiben."],
    ar: ["ما مقصود الآية المعروضة في ضوء سبب النزول المروي عن ابن عباس وغيره؟", ["أن مبغضه الذي عيّره بالانقطاع هو المنقطع", "أن النبي ﷺ لن يترك ذرية من أي نوع", "أن يقطع النبي ﷺ أقاربه المعادين", "أن قريشًا ستنقطع عن طرق تجارتها"], "لما مات أبناء النبي ﷺ عيّره بعض خصومه، ويُذكر غالبًا العاص بن وائل، بأنه أبتر لا عقب له من الذكور، فأجابت السورة بأن مبغضه هو المقطوع من الخير والذكر، أما النبي ﷺ فذكره ورسالته باقيان."] },
];
